"""Command line entry point: `ferrytide export`."""

from __future__ import annotations

import argparse
import sys
from datetime import date
from pathlib import Path

from .export import to_csv, to_ics
from .timetable import load_sailings, sailings_for

WRITERS = {"csv": to_csv, "ics": to_ics}


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="ferrytide")
    commands = parser.add_subparsers(dest="command", required=True)
    export = commands.add_parser("export", help="export one route's sailings for a day")
    export.add_argument("--route", required=True, help="route code, e.g. north-sound")
    export.add_argument("--date", type=date.fromisoformat, default=date.today(), help="YYYY-MM-DD")
    export.add_argument("--format", choices=sorted(WRITERS), default="csv")
    export.add_argument("--output", type=Path, help="write here instead of stdout")
    export.add_argument("--data", type=Path, default=Path("data/sailings.csv"))
    return parser


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    sailings = sailings_for(load_sailings(args.data), args.route, args.date)
    text = WRITERS[args.format](sailings)
    if args.output:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(text, encoding="utf-8")
    else:
        sys.stdout.write(text)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

