from datetime import date, datetime

from ferrytide.export import to_csv, to_ics
from ferrytide.timetable import Sailing, sailings_for


def sailing(hour, status="scheduled", route="north-sound", day=9):
    return Sailing(route, datetime(2026, 11, day, hour, 0), datetime(2026, 11, day, hour, 50), "MV Kittiwake", status)


def test_sailings_for_filters_route_and_day_in_order():
    rows = [sailing(12), sailing(7), sailing(9, route="south-isles"), sailing(7, day=10)]
    assert [s.departs.hour for s in sailings_for(rows, "north-sound", date(2026, 11, 9))] == [7, 12]


def test_csv_has_one_row_per_sailing():
    lines = to_csv([sailing(7), sailing(9, "cancelled")]).splitlines()
    assert lines[0] == "route,departs,arrives,vessel,status"
    assert lines[2].endswith(",cancelled")


def test_ics_marks_cancelled_sailings():
    text = to_ics([sailing(9, "cancelled")])
    assert text.startswith("BEGIN:VCALENDAR")
    assert "STATUS:CANCELLED" in text

