// quillmark command line: `quillmark build`.
import { parseArgs } from "node:util";
import { fileURLToPath } from "node:url";
import { buildSite } from "./site.ts";

const USAGE = "usage: quillmark build [--out DIR] [--content DIR] [--base-url URL] [--drafts]";

export async function main(argv: string[]): Promise<number> {
  const { positionals, values } = parseArgs({
    args: argv,
    allowPositionals: true,
    options: {
      out: { type: "string", default: "dist" },
      content: { type: "string", default: "content" },
      "base-url": { type: "string", default: "" },
      drafts: { type: "boolean", default: false },
    },
  });
  if (positionals[0] !== "build") {
    console.error(USAGE);
    return 2;
  }
  const pages = await buildSite({
    contentDir: values.content,
    outDir: values.out,
    baseUrl: values["base-url"],
    includeDrafts: values.drafts,
  });
  console.log(`quillmark: wrote ${pages} pages to ${values.out}`);
  return 0;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  process.exitCode = await main(process.argv.slice(2));
}

