// Collects the posts under the content directory and writes one page per post plus an index.
import { mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { pageShell, renderMarkdown } from "./render.ts";

export interface SiteOptions {
  contentDir: string;
  outDir: string;
  baseUrl: string;
  includeDrafts: boolean;
}

export interface Post {
  slug: string;
  title: string;
  draft: boolean;
  body: string;
}

export function parsePost(slug: string, source: string): Post {
  const match = /^---\n([\s\S]*?)\n---\n/.exec(source);
  const meta = new Map<string, string>();
  for (const line of (match?.[1] ?? "").split("\n")) {
    const at = line.indexOf(":");
    if (at > 0) meta.set(line.slice(0, at).trim(), line.slice(at + 1).trim());
  }
  return {
    slug,
    title: meta.get("title") ?? slug,
    draft: meta.get("draft") === "true",
    body: match ? source.slice(match[0].length) : source,
  };
}

export async function buildSite(options: SiteOptions): Promise<number> {
  const files = (await readdir(options.contentDir)).filter((name) => name.endsWith(".md")).sort();
  const posts: Post[] = [];
  for (const name of files) {
    const source = await readFile(join(options.contentDir, name), "utf8");
    const post = parsePost(name.replace(/\.md$/, ""), source);
    if (!post.draft || options.includeDrafts) posts.push(post);
  }
  await mkdir(options.outDir, { recursive: true });
  for (const post of posts) {
    const html = pageShell(post.title, renderMarkdown(post.body), options.baseUrl);
    await writeFile(join(options.outDir, `${post.slug}.html`), html);
  }
  const links = posts.map((p) => `<li><a href="${options.baseUrl}/${p.slug}.html">${p.title}</a></li>`);
  await writeFile(join(options.outDir, "index.html"), pageShell("Letters", `<ul>\n${links.join("\n")}\n</ul>`, options.baseUrl));
  return posts.length + 1;
}

