import { test } from "node:test";
import assert from "node:assert/strict";
import { pageShell, renderMarkdown } from "../src/render.ts";

test("headings, paragraphs, emphasis and links", () => {
  assert.equal(
    renderMarkdown("# Hello\n\nA *small* [link](https://x.example)."),
    '<h1>Hello</h1>\n<p>A <em>small</em> <a href="https://x.example">link</a>.</p>',
  );
});

test("html in the text is escaped", () => {
  assert.equal(renderMarkdown("1 < 2 & 3"), "<p>1 &lt; 2 &amp; 3</p>");
});

test("the page shell links the stylesheet under the base url", () => {
  assert.match(pageShell("T", "<p>x</p>", "https://letters.example"), /href="https:\/\/letters\.example\/style\.css"/);
});

