"""Formatting the cellar for the terminal or a spreadsheet."""

from __future__ import annotations

import csv
import io

from .cellar import Bottle

SORT_KEYS = {
    "name": lambda b: (b.name.lower(), b.vintage),
    "region": lambda b: (b.region.lower(), b.name.lower()),
    "vintage": lambda b: (b.vintage, b.name.lower()),
}

COLUMNS = ("name", "producer", "region", "vintage", "quantity", "window")


def as_csv(bottles: list[Bottle]) -> str:
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(COLUMNS)
    for b in bottles:
        writer.writerow([getattr(b, column) for column in COLUMNS])
    return out.getvalue()


def as_table(bottles: list[Bottle]) -> str:
    rows = [COLUMNS] + [tuple(str(getattr(b, c)) for c in COLUMNS) for b in bottles]
    widths = [max(len(row[i]) for row in rows) for i in range(len(COLUMNS))]
    lines = ("  ".join(cell.ljust(w) for cell, w in zip(row, widths)).rstrip() for row in rows)
    return "".join(line + "\n" for line in lines)

