export function parseCommandLine(argv: string[]): Args {
  const args: Args = { command: argv[0] ?? "", input: "", maxPoints: 500, out: "-" };
  for (let i = 1; i < argv.length; i++) {
    const arg = argv[i];
    switch (arg) {
      case "--max-points":
        args.maxPoints = Number(argv[++i]);
        break;
      case "--out":
        args.out = argv[++i];
        break;
      case "--name":
        args.name = argv[++i];
        break;
      default:
        if (!arg.startsWith("--") && !args.input) args.input = arg;
    }
  }
  return args;
}

export async function main(argv: string[]): Promise<number> {
  const args = parseCommandLine(argv);
  if (args.command !== "simplify" || !args.input) {
    console.error("usage: trailmix simplify <track.gpx> [--max-points N] [--out FILE] [--name NAME]");
    return 2;
  }
  const track = parseGpx(await readFile(args.input, "utf8"));
  const thinned = decimate(track.points, args.maxPoints);
  const xml = toGpx(args.name ?? track.name, thinned);
  if (args.out === "-") process.stdout.write(xml);
  else await writeFile(args.out, xml);
  console.error(`trailmix: ${track.points.length} -> ${thinned.length} points`);
  return 0;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
