// Minimal GPX reading and writing: one track, one segment, <trkpt lat lon> with an optional <ele>.
export interface TrackPoint {
  lat: number;
  lon: number;
  ele?: number;
}

const POINT = /<trkpt\s+lat="([-\d.]+)"\s+lon="([-\d.]+)"\s*>(?:\s*<ele>([-\d.]+)<\/ele>)?/g;

export function parseGpx(xml: string): { name: string; points: TrackPoint[] } {
  const name = /<name>([^<]*)<\/name>/.exec(xml)?.[1] ?? "track";
  const points: TrackPoint[] = [];
  for (const m of xml.matchAll(POINT)) {
    const point: TrackPoint = { lat: Number(m[1]), lon: Number(m[2]) };
    if (m[3] !== undefined) point.ele = Number(m[3]);
    points.push(point);
  }
  return { name, points };
}

export function toGpx(name: string, points: TrackPoint[]): string {
  const body = points
    .map((p) => `      <trkpt lat="${p.lat}" lon="${p.lon}">${p.ele === undefined ? "" : `<ele>${p.ele}</ele>`}</trkpt>`)
    .join("\n");
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<gpx version="1.1" creator="trailmix">',
    "  <trk>",
    `    <name>${name}</name>`,
    "    <trkseg>",
    body,
    "    </trkseg>",
    "  </trk>",
    "</gpx>",
    "",
  ].join("\n");
}

