import { test } from "node:test";
import assert from "node:assert/strict";
import { decimate, lengthKm } from "../src/simplify.ts";
import { parseCommandLine } from "../src/cli.ts";

const line = Array.from({ length: 101 }, (_, i) => ({ lat: 54 + i / 1000, lon: -3 }));

test("keeps the first and last point and at most maxPoints", () => {
  const kept = decimate(line, 11);
  assert.equal(kept.length, 11);
  assert.deepEqual(kept[0], line[0]);
  assert.deepEqual(kept.at(-1), line.at(-1));
});

test("short tracks come back unchanged", () => {
  assert.deepEqual(decimate(line.slice(0, 5), 10), line.slice(0, 5));
});

test("a straight track keeps its length", () => {
  assert.ok(Math.abs(lengthKm(decimate(line, 5)) - lengthKm(line)) < 1e-9);
});

test("command line", () => {
  assert.deepEqual(parseCommandLine(["simplify", "a.gpx", "--max-points", "50", "--out", "b.gpx"]), {
    command: "simplify", input: "a.gpx", maxPoints: 50, out: "b.gpx",
  });
});

