"""The payroll ledger: one CSV row per payslip, appended after each run."""

from __future__ import annotations

import csv
from pathlib import Path

from .payroll import Payslip

FIELDS = ["period", "employee_id", "gross", "pension", "tax", "net"]


def already_paid(path: Path, period: str) -> set[str]:
    if not path.exists():
        return set()
    with open(path, newline="", encoding="utf-8") as handle:
        return {row["employee_id"] for row in csv.DictReader(handle) if row["period"] == period}


def append(path: Path, payslips: list[Payslip]) -> None:
    new_file = not path.exists()
    with open(path, "a", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=FIELDS)
        if new_file:
            writer.writeheader()
        for p in payslips:
            writer.writerow({"period": p.period, "employee_id": p.employee_id, "gross": p.gross,
                             "pension": p.pension, "tax": p.tax, "net": p.net})

