// rotaboard command line: `rotaboard generate --team NAME [--weeks N] [--start YYYY-MM-DD]`.
import { parseArgs } from "node:util";
import { fileURLToPath } from "node:url";
import { generateRota, toCsv } from "./rota.ts";
import { TEAMS } from "./teams.ts";

export function nextMonday(from: Date): Date {
  const day = new Date(Date.UTC(from.getUTCFullYear(), from.getUTCMonth(), from.getUTCDate()));
  const offset = (8 - day.getUTCDay()) % 7 || 7;
  day.setUTCDate(day.getUTCDate() + offset);
  return day;
}

export function main(argv: string[]): number {
  const { positionals, values } = parseArgs({
    args: argv,
    allowPositionals: true,
    strict: false,
    options: {
      team: { type: "string" },
      weeks: { type: "string", default: "4" },
      start: { type: "string" },
    },
  });
  const team = typeof values.team === "string" ? TEAMS[values.team] : undefined;
  if (positionals[0] !== "generate" || !team) {
    console.error(`usage: rotaboard generate --team ${Object.keys(TEAMS).join("|")} [--weeks N] [--start YYYY-MM-DD]`);
    return 2;
  }
  const start = typeof values.start === "string" ? new Date(`${values.start}T00:00:00Z`) : nextMonday(new Date());
  process.stdout.write(toCsv(generateRota(team, start, Number(values.weeks) * 7)));
  return 0;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  process.exitCode = main(process.argv.slice(2));
}

