// Round-robin rota: every day in the range gets each of the team's shifts, staff taken in turn.
import type { Team } from "./teams.ts";

export interface Shift {
  date: string;
  shift: string;
  person: string;
}

export function generateRota(team: Team, start: Date, days: number): Shift[] {
  if (!Number.isInteger(days) || days < 1) throw new RangeError("days must be a positive whole number");
  const rota: Shift[] = [];
  let turn = 0;
  for (let i = 0; i < days; i++) {
    const date = new Date(start.getTime() + i * 86_400_000).toISOString().slice(0, 10);
    for (const shift of team.shifts) {
      rota.push({ date, shift, person: team.staff[turn % team.staff.length] });
      turn++;
    }
  }
  return rota;
}

export function toCsv(shifts: Shift[]): string {
  return ["date,shift,person", ...shifts.map((s) => `${s.date},${s.shift},${s.person}`)].join("\n") + "\n";
}

