"""Scaling a recipe to a different number of servings."""

from __future__ import annotations

from dataclasses import replace

from .recipe import Ingredient, Recipe

TSP_PER_TBSP = 3


def _tidy(ingredient: Ingredient) -> Ingredient:
    """Express large teaspoon amounts in tablespoons."""
    if ingredient.unit == "tsp" and ingredient.quantity >= TSP_PER_TBSP:
        return replace(ingredient, quantity=ingredient.quantity / TSP_PER_TBSP, unit="tbsp")
    return ingredient


def scale_recipe(recipe: Recipe, servings: int) -> Recipe:
    """Return a copy of ``recipe`` with every quantity scaled to ``servings``."""
    if not isinstance(servings, int) or servings < 1:
        raise ValueError("servings must be a positive whole number")
    factor = servings / recipe.servings
    scaled = [_tidy(replace(i, quantity=i.quantity * factor)) for i in recipe.ingredients]
    return replace(recipe, servings=servings, ingredients=scaled)

