// HTTP client for the utility's meter-reading API, with retries on 5xx and network errors.
import { parseReading } from "./readings.ts";
import type { Reading } from "./readings.ts";

export interface MeterClientOptions {
  baseUrl: string;
  apiKey?: string;
  retries?: number;
  timeoutMs?: number;
  fetchImpl?: typeof fetch;
}

export class MeterError extends Error {
  status: number | undefined;
  constructor(message: string, status?: number) {
    super(message);
    this.status = status;
  }
}

export class MeterClient {
  private readonly baseUrl: string;
  private readonly apiKey: string;
  private readonly retries: number;
  private readonly timeoutMs: number;
  private readonly fetchImpl: typeof fetch;

  constructor(options: MeterClientOptions) {
    this.baseUrl = options.baseUrl.replace(/\/+$/, "");
    this.apiKey = options.apiKey ?? "";
    this.retries = options.retries ?? 0;
    this.timeoutMs = options.timeoutMs ?? 10_000;
    this.fetchImpl = options.fetchImpl ?? fetch;
  }

  async latest(meterId: string): Promise<Reading> {
    const url = `${this.baseUrl}/meters/${encodeURIComponent(meterId)}/readings/latest`;
    let lastError: unknown;
    for (let attempt = 0; attempt <= this.retries; attempt++) {
      try {
        const response = await this.fetchImpl(url, {
          headers: { authorization: `Bearer ${this.apiKey}` },
          signal: AbortSignal.timeout(this.timeoutMs),
        });
        if (response.status >= 500) throw new MeterError(`server error ${response.status}`, response.status);
        if (!response.ok) {
