"""A vessel's cargo manifest for one voyage."""

from __future__ import annotations

from dataclasses import dataclass, field


class OverweightError(ValueError):
    """Adding the container would take the vessel over its payload limit."""


@dataclass(frozen=True)
class Container:
    number: str           # ISO 6346, e.g. MSKU1234565
    iso_type: str         # e.g. 22G1, 45R1
    gross_kg: int | None  # declared gross weight, None if the shipper sent none
    vgm_verified: bool = False
    hazardous: bool = False


@dataclass
class Manifest:
    vessel: str
    voyage: str
    max_payload_kg: int
    containers: list[Container] = field(default_factory=list)

    @property
    def total_kg(self) -> int:
        return sum(c.gross_kg or 0 for c in self.containers)

    def add(self, container: Container) -> None:
        if any(c.number == container.number for c in self.containers):
            raise ValueError(f"{container.number} is already on the manifest")
        if self.total_kg + (container.gross_kg or 0) > self.max_payload_kg:
            raise OverweightError(f"{container.number} would exceed {self.max_payload_kg} kg")
        self.containers.append(container)

    def to_rows(self) -> list[list[str]]:
        rows = [["vessel", "voyage", "container", "type", "gross_kg", "vgm", "hazardous"]]
        for c in self.containers:
            rows.append([
                self.vessel, self.voyage, c.number, c.iso_type,
                "" if c.gross_kg is None else str(c.gross_kg),
                "Y" if c.vgm_verified else "N",
                "Y" if c.hazardous else "N",
            ])
        return rows

