// Field observations exported from the survey app as CSV.
export interface Observation {
  date: string;
  site: string;
  species: string;
  count: number;
  observer: string;
  confirmed: boolean;
}

export function parseObservations(csv: string): Observation[] {
  const [header, ...lines] = csv.trim().split(/\r?\n/);
  const columns = header.split(",");
  const at = (name: string): number => {
    const index = columns.indexOf(name);
    if (index < 0) throw new Error(`missing column ${name}`);
    return index;
  };
  const col = {
    date: at("date"), site: at("site"), species: at("species"),
    count: at("count"), observer: at("observer"), status: at("status"),
  };
  return lines
    .filter((line) => line.trim())
    .map((line) => {
      const cells = line.split(",");
      return {
        date: cells[col.date],
        site: cells[col.site],
        species: cells[col.species],
        count: Number(cells[col.count]),
        observer: cells[col.observer],
        confirmed: cells[col.status] === "confirmed",
      };
    });
}

repo.src/summary.ts:
// Survey totals per species or per site. Only confirmed sightings count towards a total.
import type { Observation } from "./observations.ts";

export interface SummaryOptions {
  groupBy?: "species" | "site";
  minCount?: number;
}

export interface SummaryRow {
  key: string;
  count: number;
  visits: number;
}

export function summarize(observations: Observation[], options: SummaryOptions = {}): SummaryRow[] {
  const groupBy = options.groupBy ?? "species";
  const minCount = options.minCount ?? 1;
  const totals = new Map<string, { count: number; visits: Set<string> }>();
  for (const obs of observations) {
    if (!obs.confirmed) continue;
    const key = groupBy === "species" ? obs.species : obs.site;
    const entry = totals.get(key) ?? { count: 0, visits: new Set<string>() };
    entry.count += obs.count;
    entry.visits.add(`${obs.site}:${obs.date}`);
    totals.set(key, entry);
  }
  return [...totals]
    .map(([key, t]) => ({ key, count: t.count, visits: t.visits.size }))
    .filter((row) => row.count >= minCount)
    .sort((a, b) => b.count - a.count || a.key.localeCompare(b.key));
}

