// Formatting one predicted arrival for the station screens.
export interface Arrival {
  route: string;
  destination: string;
  expected: Date;
  cancelled?: boolean;
}

export interface FormatOptions {
  clock?: "12h" | "24h";
}

function clockTime(at: Date, clock: "12h" | "24h"): string {
  const hours = at.getUTCHours();
  const minutes = String(at.getUTCMinutes()).padStart(2, "0");
  if (clock === "24h") return `${String(hours).padStart(2, "0")}:${minutes}`;
  return `${hours % 12 || 12}:${minutes}${hours < 12 ? "am" : "pm"}`;
}

export function formatArrival(arrival: Arrival, options: FormatOptions = {}): string {
  const when = arrival.cancelled ? "cancelled" : clockTime(arrival.expected, options.clock ?? "24h");
  return `${arrival.route.padEnd(4)} ${arrival.destination.padEnd(18).slice(0, 18)} ${when}`;
}

repo.src/board.ts:
// The station screen: a header line and the next arrivals, soonest first.
import { formatArrival } from "./format.ts";
import type { Arrival } from "./format.ts";

export const SCREEN_ROWS = 8;

export function renderBoard(stopName: string, arrivals: Arrival[], now: Date): string[] {
  const upcoming = arrivals
    .filter((a) => a.expected.getTime() >= now.getTime() - 60_000)
    .sort((a, b) => a.expected.getTime() - b.expected.getTime())
    .slice(0, SCREEN_ROWS);
  return [stopName.toUpperCase(), ...upcoming.map((a) => formatArrival(a, { clock: "24h" }))];
}

repo.src/feed.ts:
// Arrivals from the operator's real-time feed (JSON), filtered to one stop.
import type { Arrival } from "./format.ts";

export interface FeedEntry {
  stop: string;
  route: string;
  headsign: string;
  expected: string;
  status?: string;
}

export function arrivalsForStop(feed: { arrivals: FeedEntry[] }, stop: string): Arrival[] {
  return feed.arrivals
    .filter((e) => e.stop === stop)
    .map((e) => ({
      route: e.route,
      destination: e.headsign,
      expected: new Date(e.expected),
      cancelled: e.status === "cancelled",
    }));
}

repo.test/format.test.ts:
import { test } from "node:test";
import assert from "node:assert/strict";
import { formatArrival } from "../src/format.ts";
import { renderBoard } from "../src/board.ts";
import { arrivalsForStop } from "../src/feed.ts";

const at = (hhmm: string) => new Date(`2026-11-07T${hhmm}:00Z`);

test("24-hour clock by default", () => {
  const row = formatArrival({ route: "12", destination: "Harbour", expected: at("08:05") });
  assert.equal(row, `${"12".padEnd(4)} ${"Harbour".padEnd(18)} 08:05`);
});

test("12-hour clock", () => {
  const row = formatArrival({ route: "3", destination: "Old Town", expected: at("13:40") }, { clock: "12h" });
  assert.ok(row.endsWith(" 1:40pm"));
});

test("cancelled runs say so", () => {
  assert.match(formatArrival({ route: "7", destination: "Airport", expected: at("09:00"), cancelled: true }), /cancelled$/);
});

test("the board shows the soonest arrivals and drops departed ones", () => {
  const feed = {
    arrivals: [
      { stop: "S1", route: "12", headsign: "Harbour", expected: "2026-11-07T08:20:00Z" },
      { stop: "S1", route: "3", headsign: "Old Town", expected: "2026-11-07T08:05:00Z" },
      { stop: "S1", route: "7", headsign: "Airport", expected: "2026-11-07T07:50:00Z" },
      { stop: "S2", route: "9", headsign: "Ring Road", expected: "2026-11-07T08:06:00Z" },
    ],
  };
  const board = renderBoard("Main Square", arrivalsForStop(feed, "S1"), at("08:00"));
  assert.deepEqual(board.map((line) => line.trim().split(/\s+/)[0]), ["MAIN", "3", "12"]);
});

