// Turns due reminders into timed sends, spaced to respect the provider's rate limit.
import type { RelayConfig } from "./config.ts";

export interface Reminder {
  phone: string;
  appointment: Date;
  template: string;
}

export interface PlannedSend {
  phone: string;
  sendAt: Date;
  body: string;
}

export function renderTemplate(template: string, appointment: Date): string {
  const iso = appointment.toISOString();
  return template.replace("{date}", iso.slice(0, 10)).replace("{time}", iso.slice(11, 16));
}

export function planSends(reminders: Reminder[], now: Date, config: RelayConfig): PlannedSend[] {
  const gapMs = Math.ceil(60_000 / config.rateLimitPerMinute);
  return reminders.map((reminder, i) => {
    const template = config.templates[reminder.template];
    if (template === undefined) throw new Error(`unknown template ${reminder.template}`);
    return {
      phone: reminder.phone,
      sendAt: new Date(now.getTime() + i * gapMs),
      body: renderTemplate(template, reminder.appointment),
    };
  });
}

