// Booking settings from config/booking.json.
import { readFileSync } from "node:fs";

export interface BookingConfig {
  maxSeatsPerOrder: number;
  currency: string;
  releaseUnpaidAfterMinutes: number;
}

export function parseBookingConfig(text: string): BookingConfig {
  const raw = JSON.parse(text) as Partial<BookingConfig>;
  return {
    maxSeatsPerOrder: raw.maxSeatsPerOrder ?? 10,
    currency: raw.currency ?? "EUR",
    releaseUnpaidAfterMinutes: raw.releaseUnpaidAfterMinutes ?? 60,
  };
