repo.src/holds.ts:
// Seat holds during online checkout: held seats are unavailable to other buyers until the hold lapses.
export const CHECKOUT_HOLD_MS = 10 * 60_000;

export interface Hold {
  orderId: string;
  seats: string[];
  expiresAt: number;
}

export class SeatHolds {
  private holds = new Map<string, Hold>();

  hold(orderId: string, seats: string[], now: number): Hold {
    const taken = seats.filter((seat) => this.isHeld(seat, now));
    if (taken.length > 0) throw new Error(`seats already held: ${taken.join(", ")}`);
    const hold = { orderId, seats: [...seats], expiresAt: now + CHECKOUT_HOLD_MS };
    this.holds.set(orderId, hold);
    return hold;
  }

  isHeld(seat: string, now: number): boolean {
    for (const hold of this.holds.values()) {
      if (hold.expiresAt > now && hold.seats.includes(seat)) return true;
    }
    return false;
  }

  release(orderId: string): void {
    this.holds.delete(orderId);
  }

  expire(now: number): string[] {
    const expired: string[] = [];
    for (const [id, hold] of this.holds) {
      if (hold.expiresAt <= now) {
        this.holds.delete(id);
        expired.push(id);
      }
    }
    return expired;
  }
}

repo.src/orders.ts:
// Orders: online checkout (seats held while paying) and box-office phone reservations (pay on collection).
import type { BookingConfig } from "./config.ts";

export interface PhoneReservation {
  reference: string;
  seats: string[];
  createdAt: number;
  paid: boolean;
}

export function checkSeatCount(seats: string[], config: BookingConfig): void {
  if (seats.length === 0) throw new Error("no seats chosen");
  if (seats.length > config.maxSeatsPerOrder) throw new Error(`at most ${config.maxSeatsPerOrder} seats per order`);
  if (new Set(seats).size !== seats.length) throw new Error("the same seat twice");
}

export function unpaidToRelease(reservations: PhoneReservation[], now: number, config: BookingConfig): string[] {
  const cutoff = now - config.releaseUnpaidAfterMinutes * 60_000;
  return reservations.filter((r) => !r.paid && r.createdAt <= cutoff).map((r) => r.reference);
}

