import { test } from "node:test";
import assert from "node:assert/strict";
import { CHECKOUT_HOLD_MS, SeatHolds } from "../src/holds.ts";

test("held seats are not available to another order", () => {
  const holds = new SeatHolds();
  holds.hold("o1", ["B4", "B5"], 0);
  assert.throws(() => holds.hold("o2", ["B5"], 1000), /B5/);
});

test("holds lapse after the checkout window", () => {
  const holds = new SeatHolds();
  holds.hold("o1", ["B4"], 0);
  assert.equal(holds.isHeld("B4", CHECKOUT_HOLD_MS - 1), true);
  assert.deepEqual(holds.expire(CHECKOUT_HOLD_MS), ["o1"]);
  assert.equal(holds.isHeld("B4", CHECKOUT_HOLD_MS), false);
});

