    { reference: "P2", seats: ["C2"], createdAt: 0, paid: true },
    { reference: "P3", seats: ["C3"], createdAt: 20 * 60_000, paid: false },
  ];
  assert.deepEqual(unpaidToRelease(reservations, 30 * 60_000, config), ["P1"]);
});

