from datetime import date, timedelta

from vaultrot.policy import Policy, select_keep
from vaultrot.prune import prune

DAYS = [date(2026, 11, 7) - timedelta(days=n) for n in range(60)]


def test_keeps_the_newest_days():
    keep = select_keep(DAYS, Policy(keep_daily=3, keep_weekly=0))
    assert keep == {date(2026, 11, 7), date(2026, 11, 6), date(2026, 11, 5)}


def test_keeps_one_backup_per_recent_week():
    keep = select_keep(DAYS, Policy(keep_daily=0, keep_weekly=3))
    assert keep == {date(2026, 11, 7), date(2026, 11, 1), date(2026, 10, 25)}


def test_prune_deletes_what_is_not_kept(tmp_path):
    for day in DAYS[:10]:
        (tmp_path / f"db-{day}.sql.gz").write_bytes(b"")
    (tmp_path / "notes.txt").write_text("not a backup")
    deleted = prune(tmp_path, Policy(keep_daily=2, keep_weekly=1))
    assert [p.name for p in deleted] == [f"db-{day}.sql.gz" for day in sorted(DAYS[2:10])]
    assert (tmp_path / "notes.txt").exists()

