// Alert settings from config/alerts.json.
import { readFileSync } from "node:fs";

export interface AlertConfig {
  tank: string;
  tempRange: [number, number];
  checkEveryMinutes: number;
  notify: string[];
}

export function parseAlertConfig(text: string): AlertConfig {
  const raw = JSON.parse(text);
  const range = raw.tempRange;
  if (!Array.isArray(range) || range.length !== 2 || !(range[0] < range[1])) {
    throw new Error("tempRange must be [low, high]");
  }
  return {
    tank: String(raw.tank ?? "tank"),
    tempRange: [range[0], range[1]],
    checkEveryMinutes: raw.checkEveryMinutes ?? 5,
    notify: raw.notify ?? [],
  };
}

export function loadAlertConfig(path = "config/alerts.json"): AlertConfig {
  return parseAlertConfig(readFileSync(path, "utf8"));
}

