// Alert rules for one tank reading. Readings carry temperature (degrees C) and pH.
import type { AlertConfig } from "./config.ts";

export interface Reading {
  at: string;
  temperature: number;
  ph: number;
}

export interface Alert {
  at: string;
  message: string;
}

export function checkReading(reading: Reading, config: AlertConfig): Alert[] {
  const [low, high] = config.tempRange;
  const alerts: Alert[] = [];
  if (reading.temperature < low) {
    alerts.push({ at: reading.at, message: `${config.tank}: temperature ${reading.temperature} below ${low}` });
  }
  if (reading.temperature > high) {
    alerts.push({ at: reading.at, message: `${config.tank}: temperature ${reading.temperature} above ${high}` });
  }
  return alerts;
}

repo.src/monitor.ts:
// Reads the newest line of the sensor log, records it, and queues alert emails for the local relay.
import { appendFile, readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { checkReading } from "./alerts.ts";
import type { Reading } from "./alerts.ts";
import { loadAlertConfig } from "./config.ts";

export function latestReading(log: string): Reading | undefined {
  const lines = log.trim().split("\n").filter(Boolean);
  if (lines.length === 0) return undefined;
  const raw = JSON.parse(lines[lines.length - 1]);
  return { at: raw.at, temperature: Number(raw.temperature), ph: Number(raw.ph) };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const config = loadAlertConfig();
  const reading = latestReading(await readFile("/var/lib/reefwatch/sensors.jsonl", "utf8"));
  if (reading) {
    await appendFile("data/history.csv", `${reading.at},${reading.temperature},${reading.ph}\n`);
    for (const alert of checkReading(reading, config)) {
      await appendFile("data/outbox.txt", `${config.notify.join(",")}\t${alert.message}\n`);
      console.log(alert.message);
    }
  }
}

