import { test } from "node:test";
import assert from "node:assert/strict";
import { checkReading } from "../src/alerts.ts";
import { parseAlertConfig } from "../src/config.ts";
import { latestReading } from "../src/monitor.ts";

const config = parseAlertConfig('{"tank": "Reef 300", "tempRange": [24.5, 26.5]}');

test("no alert inside the range", () => {
  assert.deepEqual(checkReading({ at: "t", temperature: 25.1, ph: 8.1 }, config), []);
});

test("too warm and too cold", () => {
  assert.match(checkReading({ at: "t", temperature: 27, ph: 8.1 }, config)[0].message, /above 26.5/);
  assert.match(checkReading({ at: "t", temperature: 23.9, ph: 8.1 }, config)[0].message, /below 24.5/);
});

test("a reversed range is rejected", () => {
  assert.throws(() => parseAlertConfig('{"tempRange": [27, 24]}'), /tempRange/);
});

test("latest reading from the sensor log", () => {
  const log = '{"at":"06:00","temperature":25.0,"ph":8.2}\n{"at":"06:05","temperature":25.1,"ph":8.15}\n';
  assert.deepEqual(latestReading(log), { at: "06:05", temperature: 25.1, ph: 8.15 });
});

