// Harmonic tide prediction: height(t) = datum + sum of amplitude * cos(speed * t + phase).
export interface Constituent {
  name: string;
  amplitude: number; // metres
  speed: number; // degrees per hour
  phase: number; // degrees
}

export interface Station {
  id: string;
  name: string;
  datum: number;
  constituents: Constituent[];
}

const EPOCH = Date.UTC(2026, 0, 1);

export function heightAt(station: Station, at: Date): number {
  const hours = (at.getTime() - EPOCH) / 3_600_000;
  let height = station.datum;
  for (const c of station.constituents) {
    height += c.amplitude * Math.cos(((c.speed * hours + c.phase) * Math.PI) / 180);
  }
  return Math.round(height * 1000) / 1000;
}

export function predictDay(station: Station, day: string, stepMinutes = 30): { at: string; height: number }[] {
  const start = Date.parse(`${day}T00:00:00Z`);
  const points: { at: string; height: number }[] = [];
  for (let m = 0; m < 24 * 60; m += stepMinutes) {
    const at = new Date(start + m * 60_000);
    points.push({ at: at.toISOString(), height: heightAt(station, at) });
  }
  return points;
}

