// HTTP API: GET /stations/:id/tides?day=YYYY-MM-DD returns the day's predicted heights.
import { createServer } from "node:http";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { PredictionCache } from "./cache.ts";
import { predictDay } from "./predict.ts";
import type { Station } from "./predict.ts";

export function createApp(stations: Map<string, Station>, cache = new PredictionCache<unknown>()) {
  return createServer((req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");
    const match = /^\/stations\/([\w-]+)\/tides$/.exec(url.pathname);
    const station = match ? stations.get(match[1]) : undefined;
    const day = url.searchParams.get("day") ?? new Date().toISOString().slice(0, 10);
    if (!station || !/^\d{4}-\d{2}-\d{2}$/.test(day)) {
      res.writeHead(404, { "content-type": "application/json" }).end('{"error":"not found"}');
      return;
    }
    const key = `${station.id}:${day}`;
    let body = cache.get(key);
    if (body === undefined) {
      body = { station: station.name, day, points: predictDay(station, day) };
      cache.set(key, body);
    }
    res.writeHead(200, { "content-type": "application/json" }).end(JSON.stringify(body));
  });
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const file = process.env.TIDEPOOL_STATION_FILE ?? "data/stations.json";
  const list = JSON.parse(readFileSync(file, "utf8")) as Station[];
  const port = Number(process.env.PORT ?? 8080);
  createApp(new Map(list.map((s) => [s.id, s]))).listen(port, () => console.log(`tidepool listening on ${port}`));
}

