import { test } from "node:test";
import assert from "node:assert/strict";
import { heightAt, predictDay } from "../src/predict.ts";
import { PredictionCache } from "../src/cache.ts";

const station = {
  id: "kirkhaven",
  name: "Kirkhaven Pier",
  datum: 2.1,
  constituents: [{ name: "M2", amplitude: 1.2, speed: 28.984, phase: 0 }],
};

test("height at the epoch is datum plus amplitude", () => {
  assert.equal(heightAt(station, new Date(Date.UTC(2026, 0, 1))), 3.3);
});

test("a day has 48 half-hour points", () => {
  const points = predictDay(station, "2026-11-07");
  assert.equal(points.length, 48);
  assert.equal(points[1].at, "2026-11-07T00:30:00.000Z");
});

test("cache entries expire", () => {
  let clock = 0;
  const cache = new PredictionCache<string>(() => clock);
  cache.set("k", "v");
  clock = 59_000;
  assert.equal(cache.get("k"), "v");
  clock = 60_000;
  assert.equal(cache.get("k"), undefined);
});

