"""Clinic settings from clinicq.toml. The file's location comes from CLINICQ_CONFIG."""

from __future__ import annotations

import os
import tomllib
from dataclasses import dataclass
from pathlib import Path
from zoneinfo import ZoneInfo


@dataclass(frozen=True)
class ClinicConfig:
    name: str
    tz: ZoneInfo
    hours_before: int


def config_path() -> Path:
    return Path(os.environ.get("CLINICQ_CONFIG", "clinicq.toml"))


def load_config(path: Path | None = None) -> ClinicConfig:
    with open(path or config_path(), "rb") as handle:
        data = tomllib.load(handle)
    clinic = data["clinic"]
    return ClinicConfig(
        name=clinic["name"],
        tz=ZoneInfo(clinic.get("timezone", "UTC")),
        hours_before=data.get("reminders", {}).get("hours_before", 24),
    )

