// A kiln firing: temperature readings (degrees C) taken every few minutes by the controller.
export interface Reading {
  minute: number;
  celsius: number;
}

export interface FiringSummary {
  peakCelsius: number;
  durationMinutes: number;
  maxClimbPerHour: number;
}

export function parseLog(text: string): Reading[] {
  return text
    .trim()
    .split("\n")
    .filter((line) => line && !line.startsWith("#"))
    .map((line) => {
      const [minute, celsius] = line.split(",").map(Number);
      return { minute, celsius };
    });
}

export function summarize(readings: Reading[]): FiringSummary {
  if (readings.length < 2) throw new Error("a firing needs at least two readings");
  const sorted = [...readings].sort((a, b) => a.minute - b.minute);
  let maxClimb = 0;
  for (let i = 1; i < sorted.length; i++) {
    const hours = (sorted[i].minute - sorted[i - 1].minute) / 60;
    if (hours > 0) maxClimb = Math.max(maxClimb, (sorted[i].celsius - sorted[i - 1].celsius) / hours);
  }
  return {
    peakCelsius: Math.max(...sorted.map((r) => r.celsius)),
    durationMinutes: sorted[sorted.length - 1].minute - sorted[0].minute,
    maxClimbPerHour: Math.round(maxClimb),
  };
}

