"""Live occupancy for the city's garages, from the entry/exit counters."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timedelta

STALE_AFTER = timedelta(minutes=5)


@dataclass(frozen=True)
class GarageState:
    garage: str
    spaces: int
    occupied: int
    updated_at: datetime


def apply_count(state: GarageState, entries: int, exits: int, at: datetime) -> GarageState:
    occupied = min(state.spaces, max(0, state.occupied + entries - exits))
    return GarageState(state.garage, state.spaces, occupied, at)


def availability(state: GarageState, now: datetime) -> dict:
    stale = now - state.updated_at > STALE_AFTER
    return {
        "garage": state.garage,
        "free": None if stale else state.spaces - state.occupied,
        "full": False if stale else state.occupied >= state.spaces,
        "stale": stale,
        "updated_at": state.updated_at.isoformat(),
    }

