// Plain-text logging to stdout: `<time> <LEVEL> <message> key=value ...`.
const LEVELS = ["debug", "info", "warn", "error"] as const;
type Level = (typeof LEVELS)[number];

const threshold = LEVELS.indexOf((process.env.HARVEST_LOG_LEVEL ?? "info") as Level);

export function formatLine(level: Level, message: string, fields: Record<string, unknown>, at = new Date()): string {
  const pairs = Object.entries(fields).map(([key, value]) => {
    const text = String(value);
    return `${key}=${text.includes(" ") ? JSON.stringify(text) : text}`;
  });
  return [at.toISOString(), level.toUpperCase(), message, ...pairs].join(" ");
}

export function log(level: Level, message: string, fields: Record<string, unknown> = {}): void {
  if (LEVELS.indexOf(level) >= threshold) process.stdout.write(formatLine(level, message, fields) + "\n");
}

repo.src/orders.ts:
// Farm-box orders: box sizes, add-ons and delivery days.
export const BOXES = { small: 18, medium: 26, large: 34 } as const;
export const ADD_ONS = { eggs: 4.5, bread: 3.8, flowers: 9 } as const;
export const DELIVERY_DAYS = ["tuesday", "friday"];

export interface Order {
  customer: string;
  box: keyof typeof BOXES;
  addOns: (keyof typeof ADD_ONS)[];
  deliveryDay: string;
}

export function validateOrder(input: unknown): Order {
  const o = input as Partial<Order>;
  if (typeof o.customer !== "string" || !o.customer) throw new Error("customer is required");
  if (!o.box || !(o.box in BOXES)) throw new Error("unknown box size");
  const addOns = o.addOns ?? [];
  for (const a of addOns) if (!(a in ADD_ONS)) throw new Error(`unknown add-on ${a}`);
  if (!o.deliveryDay || !DELIVERY_DAYS.includes(o.deliveryDay)) throw new Error("we deliver on tuesday and friday");
  return { customer: o.customer, box: o.box, addOns, deliveryDay: o.deliveryDay };
}

export function orderTotal(order: Order): number {
  const addOnCents = order.addOns.reduce((sum, a) => sum + Math.round(ADD_ONS[a] * 100), 0);
  return (Math.round(BOXES[order.box] * 100) + addOnCents) / 100;
}

repo.src/server.ts:
// HTTP API for the farm-box shop: POST /orders stores an order and returns its total.
import { createServer } from "node:http";
import type { IncomingMessage } from "node:http";
import { appendFile } from "node:fs/promises";
import { randomUUID } from "node:crypto";
import { fileURLToPath } from "node:url";
import { log } from "./log.ts";
import { orderTotal, validateOrder } from "./orders.ts";

const DB_PATH = process.env.HARVEST_DB_PATH ?? "data/orders.jsonl";

async function readBody(req: IncomingMessage): Promise<string> {
  let body = "";
  for await (const chunk of req) body += chunk;
  return body;
}

export const server = createServer(async (req, res) => {
  if (req.method !== "POST" || req.url !== "/orders") {
    res.writeHead(404).end();
    return;
  }
  try {
    const order = validateOrder(JSON.parse(await readBody(req)));
    const id = randomUUID();
    const total = orderTotal(order);
    await appendFile(DB_PATH, JSON.stringify({ id, ...order, total }) + "\n");
    log("info", "order created", { id, customer: order.customer, box: order.box, total });
    res.writeHead(201, { "content-type": "application/json" }).end(JSON.stringify({ id, total }));
  } catch (error) {
    log("warn", "order rejected", { reason: (error as Error).message });
    res.writeHead(400, { "content-type": "application/json" }).end(JSON.stringify({ error: (error as Error).message }));
  }
});

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT ?? 8080);
  server.listen(port, () => log("info", "listening", { port }));
}

