});

test("log lines are plain text with key=value fields", () => {
  const at = new Date("2026-11-07T08:00:00Z");
  const line = formatLine("info", "order created", { id: "o-1", customer: "Moss Farm Cafe", total: 34.3 }, at);
  assert.equal(line, '2026-11-07T08:00:00.000Z INFO order created id=o-1 customer="Moss Farm Cafe" total=34.3');
});

