// Farm-box orders: box sizes, add-ons and delivery days.
export const BOXES = { small: 18, medium: 26, large: 34 } as const;
export const ADD_ONS = { eggs: 4.5, bread: 3.8, flowers: 9 } as const;
export const DELIVERY_DAYS = ["tuesday", "friday"];

export interface Order {
  customer: string;
  box: keyof typeof BOXES;
  addOns: (keyof typeof ADD_ONS)[];
  deliveryDay: string;
}

export function validateOrder(input: unknown): Order {
  const o = input as Partial<Order>;
  if (typeof o.customer !== "string" || !o.customer) throw new Error("customer is required");
  if (!o.box || !(o.box in BOXES)) throw new Error("unknown box size");
  const addOns = o.addOns ?? [];
  for (const a of addOns) if (!(a in ADD_ONS)) throw new Error(`unknown add-on ${a}`);
  if (!o.deliveryDay || !DELIVERY_DAYS.includes(o.deliveryDay)) throw new Error("we deliver on tuesday and friday");
  return { customer: o.customer, box: o.box, addOns, deliveryDay: o.deliveryDay };
}

export function orderTotal(order: Order): number {
  const addOnCents = order.addOns.reduce((sum, a) => sum + Math.round(ADD_ONS[a] * 100), 0);
  return (Math.round(BOXES[order.box] * 100) + addOnCents) / 100;
}

