"""Overtime: hours over the weekly contract, and all hours worked on bank holidays, at time and a half."""

from __future__ import annotations

from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal

from .timesheet import Entry

OVERTIME_RATE = Decimal("1.5")
BANK_HOLIDAYS_2026 = {date(2026, 1, 1), date(2026, 4, 3), date(2026, 4, 6), date(2026, 5, 4), date(2026, 5, 25),
                      date(2026, 8, 31), date(2026, 12, 25), date(2026, 12, 28)}


def week_start(day: date) -> date:
    return day - timedelta(days=day.weekday())


def weekly_hours(entries: list[Entry]) -> dict[tuple[str, date], float]:
    totals: dict[tuple[str, date], float] = defaultdict(float)
    for e in entries:
        totals[(e.person, week_start(e.day))] += e.hours
    return dict(totals)


def overtime(entries: list[Entry], contract_hours: dict[str, float]) -> dict[str, float]:
    """Overtime hours per person."""
    result: dict[str, float] = defaultdict(float)
    for (person, _), hours in weekly_hours(entries).items():
        result[person] += max(0.0, hours - contract_hours.get(person, 37.5))
    for e in entries:
        if e.day in BANK_HOLIDAYS_2026:
            result[e.person] += e.hours
    return {person: round(h, 2) for person, h in sorted(result.items()) if h > 0}


def overtime_pay(hours: float, hourly_rate: Decimal) -> Decimal:
    return (Decimal(str(hours)) * hourly_rate * OVERTIME_RATE).quantize(Decimal("0.01"))

