// Client for the courier's tracking API.
import { normaliseStatus } from "./status.ts";
import type { ParcelStatus } from "./status.ts";

export interface TrackingClientOptions {
  baseUrl: string;
  apiKey: string;
  maxRetries?: number;
  fetchImpl?: typeof fetch;
}

export class TrackingClient {
  private options: Required<TrackingClientOptions>;

  constructor(options: TrackingClientOptions) {
    this.options = { maxRetries: 0, fetchImpl: fetch, ...options };
  }

  async track(parcelId: string): Promise<ParcelStatus> {
    const { baseUrl, apiKey, maxRetries, fetchImpl } = this.options;
    for (let attempt = 0; ; attempt++) {
      const response = await fetchImpl(`${baseUrl}/v1/parcels/${encodeURIComponent(parcelId)}`, {
        headers: { "x-api-key": apiKey },
      });
      if (response.ok) return normaliseStatus(await response.json());
      if (response.status < 500 || attempt >= maxRetries) {
        throw new Error(`tracking ${parcelId}: HTTP ${response.status}`);
      }
    }
  }
}

