// The courier's status codes, mapped to the states the shop shows customers.
export type ParcelState = "label-created" | "in-transit" | "out-for-delivery" | "delivered" | "exception";

export interface ParcelStatus {
  parcelId: string;
  state: ParcelState;
  updatedAt: string;
}

const CODES: Record<string, ParcelState> = {
  LC: "label-created", IT: "in-transit", AR: "in-transit", OD: "out-for-delivery", DL: "delivered",
};

export function normaliseStatus(body: { id: string; code: string; ts: string }): ParcelStatus {
  return { parcelId: body.id, state: CODES[body.code] ?? "exception", updatedAt: body.ts };
}

