// Nightly sync: refresh the status of every open parcel and write the results for the shop.
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { TrackingClient } from "./tracking.ts";
import type { ParcelStatus } from "./status.ts";

export async function syncAll(client: TrackingClient, parcelIds: string[]) {
  const ok: ParcelStatus[] = [];
  const failed: string[] = [];
  for (const id of parcelIds) {
    try {
      ok.push(await client.track(id));
    } catch {
      failed.push(id);
    }
  }
  return { ok, failed };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const client = new TrackingClient({
    baseUrl: process.env.COURIER_API_URL ?? "https://api.swiftcourier.example",
    apiKey: process.env.COURIER_API_KEY ?? "",
  });
  const ids = JSON.parse(await readFile("data/open-parcels.json", "utf8")) as string[];
  const result = await syncAll(client, ids);
  await writeFile("data/statuses.json", JSON.stringify(result.ok, null, 2));
  console.log(`synced ${result.ok.length}, failed ${result.failed.length}`);
}

