// Customer emails when a parcel's state changes: one per change, never the same one twice.
import type { ParcelState, ParcelStatus } from "./status.ts";

const MESSAGES: Record<ParcelState, string> = {
  "label-created": "Your order is packed and waiting for the courier.",
  "in-transit": "Your parcel is on its way.",
  "out-for-delivery": "Your parcel is out for delivery today.",
  delivered: "Your parcel has been delivered.",
  exception: "There is a problem with your delivery; we will be in touch.",
};

export interface Notification {
  parcelId: string;
  subject: string;
  body: string;
}

export function changes(previous: Map<string, ParcelState>, current: ParcelStatus[]): ParcelStatus[] {
  return current.filter((s) => previous.get(s.parcelId) !== s.state);
}

export function notificationsFor(
  previous: Map<string, ParcelState>,
  current: ParcelStatus[],
  orderOf: (parcelId: string) => string,
): Notification[] {
  return changes(previous, current).map((s) => ({
    parcelId: s.parcelId,
    subject: `Order ${orderOf(s.parcelId)}: ${s.state.replace(/-/g, " ")}`,
    body: MESSAGES[s.state],
  }));
}

export function stuckParcels(statuses: ParcelStatus[], now: Date, days = 4): string[] {
  const limit = now.getTime() - days * 86_400_000;
  return statuses.filter((s) => s.state === "in-transit" && Date.parse(s.updatedAt) < limit).map((s) => s.parcelId);
}

