"""Rent payments and arrears per tenancy."""

from __future__ import annotations

import csv
from collections import defaultdict
from dataclasses import dataclass
from datetime import date
from decimal import Decimal
from pathlib import Path


@dataclass(frozen=True)
class Payment:
    tenancy: str
    paid_on: date
    amount: Decimal
    method: str  # "standing order", "card" or "cash"


def load_payments(path: Path) -> list[Payment]:
    with open(path, newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    return [Payment(r["tenancy"], date.fromisoformat(r["paid_on"]), Decimal(r["amount"]), r["method"]) for r in rows]


def arrears(rent_due: dict[str, Decimal], payments: list[Payment], months: int) -> dict[str, Decimal]:
    """What each tenancy still owes after ``months`` months of rent, not counting late fees."""
    paid: dict[str, Decimal] = defaultdict(Decimal)
    for p in payments:
        paid[p.tenancy] += p.amount
    owed = {t: monthly * months - paid[t] for t, monthly in rent_due.items()}
    return {t: amount for t, amount in sorted(owed.items()) if amount > 0}


def payment_methods(payments: list[Payment]) -> dict[str, int]:
    counts: dict[str, int] = defaultdict(int)
    for p in payments:
        counts[p.method] += 1
    return dict(sorted(counts.items()))


def statement(tenancy: str, payments: list[Payment], monthly: Decimal, months: int) -> list[str]:
    """A running statement for one tenancy: rent charged, payments made, balance."""
    balance = monthly * months
    lines = [f"Rent for {months} months: {balance}"]
    for p in sorted((p for p in payments if p.tenancy == tenancy), key=lambda p: p.paid_on):
        balance -= p.amount
        lines.append(f"{p.paid_on}  {p.method:<16} -{p.amount}  balance {balance}")
    return lines

