// Leveled logging to stderr. LOOM_LOG_LEVEL picks the minimum level (debug, info, warn, error).
const ORDER = ["debug", "info", "warn", "error"];

export function currentLevel(env: Record<string, string | undefined> = process.env): string {
  const level = (env.LOOM_LOG_LEVEL ?? "info").toLowerCase();
  return ORDER.includes(level) ? level : "info";
}

export function shouldLog(level: string, minimum = currentLevel()): boolean {
  return ORDER.indexOf(level) >= ORDER.indexOf(minimum);
}

export function log(level: string, message: string): void {
  if (shouldLog(level)) process.stderr.write(`${new Date().toISOString()} ${level} ${message}\n`);
}

