// Dye lots: an order line is always filled from one lot, the smallest that has enough skeins.
import { log } from "./log.ts";

export interface Lot {
  lot: string;
  colour: string;
  skeins: number;
}

export function pickLot(lots: Lot[], colour: string, skeins: number): Lot | undefined {
  const candidates = lots
    .filter((l) => l.colour === colour && l.skeins >= skeins)
    .sort((a, b) => a.skeins - b.skeins);
  log("debug", `pickLot ${colour} x${skeins}: ${candidates.map((c) => c.lot).join(",") || "none"}`);
  return candidates[0];
}

