// Yarn prices: per skein by weight class, with 10% off whole bags of ten from one dye lot.
export const PRICE_PER_SKEIN: Record<string, number> = { lace: 6.5, "4ply": 7.25, dk: 7.95, aran: 8.5, chunky: 9.75 };

export interface Line {
  weight: string;
  colour: string;
  skeins: number;
}

export function linePrice(line: Line): number {
  const each = PRICE_PER_SKEIN[line.weight];
  if (each === undefined) throw new Error(`unknown yarn weight ${line.weight}`);
  if (!Number.isInteger(line.skeins) || line.skeins < 1) throw new Error("skeins must be a positive whole number");
  const bags = Math.floor(line.skeins / 10);
  const loose = line.skeins % 10;
  const cents = Math.round(bags * 10 * each * 0.9 * 100) + Math.round(loose * each * 100);
  return cents / 100;
}

export function orderTotal(lines: Line[], freeShippingFrom = 60): { goods: number; shipping: number; total: number } {
  const goods = Math.round(lines.reduce((sum, l) => sum + linePrice(l), 0) * 100) / 100;
  const shipping = goods >= freeShippingFrom ? 0 : 4.5;
  return { goods, shipping, total: Math.round((goods + shipping) * 100) / 100 };
}


export interface DyeLotStock {
  lot: string;
  colour: string;
  weight: string;
  skeins: number;
}

export function lowColours(stock: DyeLotStock[], minimumSkeins = 20): string[] {
  const totals = new Map<string, number>();
  for (const s of stock) totals.set(`${s.weight}/${s.colour}`, (totals.get(`${s.weight}/${s.colour}`) ?? 0) + s.skeins);
  return [...totals].filter(([, skeins]) => skeins < minimumSkeins).map(([key]) => key).sort();
}

export function stockValue(stock: DyeLotStock[]): number {
  const cents = stock.reduce((sum, s) => sum + Math.round((PRICE_PER_SKEIN[s.weight] ?? 0) * 100) * s.skeins, 0);
  return cents / 100;
}

export function wholesalePrice(retail: number, discountPercent = 35): number {
  return Math.round(retail * (1 - discountPercent / 100) * 100) / 100;
}

