"""Seed swaps: members take packets at the swap table and bring saved seed back in the autumn."""

from __future__ import annotations

from collections import Counter
from dataclasses import dataclass, field
from datetime import date

PACKETS_PER_YEAR = 10


@dataclass
class SwapLog:
    taken: list[tuple[date, str, str]] = field(default_factory=list)  # (day, member, variety code)
    returned: list[tuple[date, str, str]] = field(default_factory=list)

    def take(self, day: date, member: str, code: str) -> None:
        this_year = sum(1 for d, m, _ in self.taken if m == member and d.year == day.year)
        if this_year >= PACKETS_PER_YEAR:
            raise ValueError(f"{member} has taken {PACKETS_PER_YEAR} packets this year")
        self.taken.append((day, member, code))

    def give_back(self, day: date, member: str, code: str) -> None:
        self.returned.append((day, member, code))

    def owed_back(self, year: int) -> dict[str, list[str]]:
        """Varieties each member took in ``year`` and has not yet returned saved seed for."""
        back = Counter((m, c) for d, m, c in self.returned if d.year in (year, year + 1))
        owed: dict[str, list[str]] = {}
        for d, member, code in self.taken:
            if d.year != year:
                continue
            if back[(member, code)] > 0:
                back[(member, code)] -= 1
            else:
                owed.setdefault(member, []).append(code)
        return owed


def germination_rate(sown: int, came_up: int) -> float:
    if sown <= 0 or not 0 <= came_up <= sown:
        raise ValueError("came_up must be between 0 and the number sown")
    return round(100 * came_up / sown, 1)


def needs_testing(last_tested: dict[str, int], this_year: int, every_years: int = 3) -> list[str]:
    """Varieties whose germination was last tested more than ``every_years`` years ago."""
    return sorted(code for code, year in last_tested.items() if this_year - year > every_years)


def swap_report(log: SwapLog, year: int) -> list[str]:
    owed = log.owed_back(year)
    return [f"{member}: please return saved seed of {', '.join(sorted(codes))}" for member, codes in sorted(owed.items())]

