// shelfscan command line: `shelfscan sync [--supplier NAME] [--dry-run]`.
import { fileURLToPath } from "node:url";
import { applyChanges, diffPrices } from "./prices.ts";
import { loadCatalogue, loadSupplierFeed, saveCatalogue } from "./store.ts";

export function parseFlags(argv: string[]): { command: string; supplier: string; dryRun: boolean } {
  const flags = { command: argv[0] ?? "", supplier: "northbound", dryRun: false };
  for (let i = 1; i < argv.length; i++) {
    if (argv[i] === "--dry-run") flags.dryRun = true;
    else if (argv[i] === "--supplier") flags.supplier = argv[++i];
    else throw new Error(`unknown option ${argv[i]}`);
  }
  return flags;
}

export async function main(argv: string[]): Promise<number> {
  const flags = parseFlags(argv);
  if (flags.command !== "sync") {
    console.error("usage: shelfscan sync [--supplier NAME] [--dry-run]");
    return 2;
  }
  const catalogue = await loadCatalogue();
  const changes = diffPrices(catalogue, await loadSupplierFeed(flags.supplier));
  for (const c of changes) console.log(`${c.isbn}  ${c.from.toFixed(2)} -> ${c.to.toFixed(2)}  ${c.title}`);
  if (flags.dryRun) {
    console.log(`${changes.length} price changes (dry run, nothing written)`);
    return 0;
  }
  await saveCatalogue(applyChanges(catalogue, changes));
  console.log(`${changes.length} price changes written`);
  return 0;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  process.exitCode = await main(process.argv.slice(2));
}

