// Comparing our shelf prices with the suppliers' recommended retail prices.
export interface Book {
  isbn: string;
  title: string;
  price: number;
}

export interface PriceChange {
  isbn: string;
  title: string;
  from: number;
  to: number;
}

export function diffPrices(catalogue: Book[], feed: Map<string, number>): PriceChange[] {
  const changes: PriceChange[] = [];
  for (const book of catalogue) {
    const rrp = feed.get(book.isbn);
    if (rrp !== undefined && Math.round(rrp * 100) !== Math.round(book.price * 100)) {
      changes.push({ isbn: book.isbn, title: book.title, from: book.price, to: rrp });
    }
  }
  return changes;
}

export function applyChanges(catalogue: Book[], changes: PriceChange[]): Book[] {
  const next = new Map(changes.map((c) => [c.isbn, c.to]));
  return catalogue.map((book) => ({ ...book, price: next.get(book.isbn) ?? book.price }));
}

