// Our catalogue (data/catalogue.json) and the suppliers' price feeds (data/feeds/<supplier>.csv).
import { readFile, writeFile } from "node:fs/promises";
import type { Book } from "./prices.ts";

export async function loadCatalogue(path = "data/catalogue.json"): Promise<Book[]> {
  return JSON.parse(await readFile(path, "utf8")) as Book[];
}

export async function saveCatalogue(books: Book[], path = "data/catalogue.json"): Promise<void> {
  await writeFile(path, JSON.stringify(books, null, 2) + "\n");
}

export async function loadSupplierFeed(supplier: string): Promise<Map<string, number>> {
  const text = await readFile(`data/feeds/${supplier}.csv`, "utf8");
  const feed = new Map<string, number>();
  for (const line of text.trim().split("\n").slice(1)) {
    const [isbn, rrp] = line.split(",");
    feed.set(isbn, Number(rrp));
  }
  return feed;
}

