// Reorders: titles selling faster than the shelf can hold, rounded up to the supplier's pack size.
export interface SalesLine {
  isbn: string;
  title: string;
  onShelf: number;
  soldLast28Days: number;
  packSize: number;
}

export function weeksOfStock(line: SalesLine): number {
  const weekly = line.soldLast28Days / 4;
  return weekly === 0 ? Infinity : Math.round((line.onShelf / weekly) * 10) / 10;
}

export function reorderQuantity(line: SalesLine, targetWeeks = 6): number {
  const wanted = Math.ceil((line.soldLast28Days / 4) * targetWeeks) - line.onShelf;
  if (wanted <= 0) return 0;
  return Math.ceil(wanted / line.packSize) * line.packSize;
}

export function reorderSheet(lines: SalesLine[], targetWeeks = 6): string[] {
  return lines
    .map((line) => ({ line, qty: reorderQuantity(line, targetWeeks) }))
    .filter(({ qty }) => qty > 0)
    .sort((a, b) => weeksOfStock(a.line) - weeksOfStock(b.line))
    .map(({ line, qty }) => `${line.isbn}  ${String(qty).padStart(4)}  ${line.title}`);
}

export function slowSellers(lines: SalesLine[], weeks = 26): SalesLine[] {
  return lines.filter((line) => line.onShelf > 0 && weeksOfStock(line) > weeks);
}

