"""Settings, each overridable by an environment variable: HARBORLIGHT_ + the field name in capitals."""

from __future__ import annotations

import os
from dataclasses import dataclass, fields
from typing import Mapping

PREFIX = "HARBORLIGHT_"


@dataclass(frozen=True)
class Settings:
    buoy_api: str = "http://buoys.harbor.example/api"
    request_timeout: float = 5.0
    poll_interval: int = 300
    stations: str = "B1,B2,B4"


def load(env: Mapping[str, str] | None = None) -> Settings:
    env = os.environ if env is None else env
    values = {}
    for field in fields(Settings):
        raw = env.get(PREFIX + field.name.upper())
        if raw is not None:
            values[field.name] = type(field.default)(raw)
    return Settings(**values)

