"""Poll every buoy once and print one JSON line per reading."""

from __future__ import annotations

import json
import sys
import urllib.request

from .settings import Settings, load


def fetch(settings: Settings, station: str) -> dict:
    url = f"{settings.buoy_api}/stations/{station}/latest"
    with urllib.request.urlopen(url, timeout=settings.request_timeout) as response:
        return json.load(response)


def main() -> int:
    settings = load()
    failures = 0
    for station in settings.stations.split(","):
        try:
            print(json.dumps({"station": station, **fetch(settings, station)}))
        except OSError as exc:
            failures += 1
            print(f"{station}: {exc}", file=sys.stderr)
    return 1 if failures else 0


if __name__ == "__main__":
    raise SystemExit(main())

