"""Buoy readings and the daily summary for the harbour master."""

from __future__ import annotations

import statistics
from dataclasses import dataclass
from datetime import datetime


@dataclass(frozen=True)
class Reading:
    station: str
    at: datetime
    wave_height_m: float
    wind_knots: float
    water_temp_c: float


def parse(station: str, raw: dict) -> Reading:
    return Reading(
        station=station,
        at=datetime.fromisoformat(raw["time"]),
        wave_height_m=float(raw["hs"]),
        wind_knots=float(raw["wind"]),
        water_temp_c=float(raw["sst"]),
    )


def daily_summary(readings: list[Reading]) -> dict[str, dict[str, float]]:
    by_station: dict[str, list[Reading]] = {}
    for r in readings:
        by_station.setdefault(r.station, []).append(r)
    return {
        station: {
            "max_wave_m": max(r.wave_height_m for r in rs),
            "mean_wind_knots": round(statistics.fmean(r.wind_knots for r in rs), 1),
            "water_temp_c": rs[-1].water_temp_c,
        }
        for station, rs in sorted(by_station.items())
    }


def small_craft_warning(summary: dict[str, dict[str, float]]) -> list[str]:
    return [s for s, v in summary.items() if v["max_wave_m"] >= 2.0 or v["mean_wind_knots"] >= 22]


def beaufort(knots: float) -> int:
    """Beaufort force for a mean wind speed in knots."""
    limits = [1, 4, 7, 11, 17, 22, 28, 34, 41, 48, 56, 64]
    return next((force for force, limit in enumerate(limits) if knots < limit), 12)


def shipping_line(station: str, values: dict[str, float]) -> str:
    force = beaufort(values["mean_wind_knots"])
    return f"{station}: wind force {force}, waves up to {values['max_wave_m']:.1f} m, sea {values['water_temp_c']:.1f} C"

