// Signing people up for a supper; when the table is full, extra guests can wait for a free place.
import type { PotluckConfig } from "./config.ts";

export interface PotluckEvent {
  id: string;
  guests: string[];
  waiting: string[];
}

export class EventFull extends Error {}

export function signUp(event: PotluckEvent, person: string, config: PotluckConfig): "confirmed" | "waitlisted" {
  if (event.guests.includes(person) || event.waiting.includes(person)) throw new Error(`${person} is already signed up`);
  if (event.guests.length < config.maxGuestsPerHost) {
    event.guests.push(person);
    return "confirmed";
  }
  if (!config.waitlist) throw new EventFull(`event ${event.id} is full`);
  event.waiting.push(person);
  return "waitlisted";
}

export function cancel(event: PotluckEvent, person: string): string | undefined {
  const index = event.guests.indexOf(person);
  if (index < 0) {
    event.waiting = event.waiting.filter((p) => p !== person);
    return undefined;
  }
  event.guests.splice(index, 1);
  const next = event.waiting.shift();
  if (next) event.guests.push(next);
  return next;
}

