// Who brings what: each guest signs up a dish, and the host wants a balance of courses.
export type Course = "starter" | "main" | "side" | "dessert" | "drink";

export interface Dish {
  guest: string;
  name: string;
  course: Course;
  vegetarian: boolean;
}

const WANTED: Record<Course, number> = { starter: 2, main: 3, side: 3, dessert: 2, drink: 2 };

export function stillWanted(dishes: Dish[]): Partial<Record<Course, number>> {
  const counts = new Map<Course, number>();
  for (const d of dishes) counts.set(d.course, (counts.get(d.course) ?? 0) + 1);
  const wanted: Partial<Record<Course, number>> = {};
  for (const course of Object.keys(WANTED) as Course[]) {
    const missing = WANTED[course] - (counts.get(course) ?? 0);
    if (missing > 0) wanted[course] = missing;
  }
  return wanted;
}

export function addDish(dishes: Dish[], dish: Dish): Dish[] {
  const clash = dishes.find((d) => d.name.trim().toLowerCase() === dish.name.trim().toLowerCase());
  if (clash) throw new Error(`${clash.guest} is already bringing ${clash.name}`);
  const mains = dishes.filter((d) => d.course === "main");
  if (dish.course === "main" && !dish.vegetarian && mains.length === WANTED.main - 1 && !mains.some((d) => d.vegetarian)) {
    throw new Error("the last main has to be vegetarian");
  }
  return [...dishes, dish];
}


export function allergyWarnings(dishes: Dish[], allergens: Record<string, string[]>): string[] {
  const warnings: string[] = [];
  for (const d of dishes) {
    const found = allergens[d.name.trim().toLowerCase()] ?? [];
    if (found.length > 0) warnings.push(`${d.name} (from ${d.guest}) contains ${found.join(", ")}`);
  }
  return warnings;
}

export function reminderFor(dishes: Dish[], guest: string): string {
  const mine = dishes.filter((d) => d.guest === guest).map((d) => d.name);
  return mine.length ? `${guest}, you are bringing: ${mine.join(", ")}` : `${guest}, you have not signed up a dish yet`;
}

