"""Finding renders that have not been touched for a while."""

from __future__ import annotations

from pathlib import Path

DAY = 86_400


def old_files(root: Path, pattern: str, max_age_days: int, now: float) -> list[Path]:
    if max_age_days < 1:
        raise ValueError("max_age_days must be at least 1")
    cutoff = now - max_age_days * DAY
    return sorted(p for p in root.rglob(pattern) if p.is_file() and p.stat().st_mtime < cutoff)

