"""Disk usage of the render cache per show and per shot, for the weekly production meeting."""

from __future__ import annotations

from collections import defaultdict
from pathlib import Path


def usage_by_show(root: Path) -> dict[str, int]:
    """Bytes used per show; renders live under <root>/<show>/<shot>/..."""
    totals: dict[str, int] = defaultdict(int)
    for path in root.rglob("*"):
        if path.is_file():
            totals[path.relative_to(root).parts[0]] += path.stat().st_size
    return dict(sorted(totals.items(), key=lambda kv: -kv[1]))


def heaviest_shots(root: Path, count: int = 10) -> list[tuple[str, int]]:
    totals: dict[str, int] = defaultdict(int)
    for path in root.rglob("*"):
        parts = path.relative_to(root).parts
        if path.is_file() and len(parts) >= 3:
            totals[f"{parts[0]}/{parts[1]}"] += path.stat().st_size
    return sorted(totals.items(), key=lambda kv: -kv[1])[:count]


def human(size: float) -> str:
    for unit in ("B", "KB", "MB", "GB"):
        if size < 1024:
            return f"{size:.0f} {unit}"
        size /= 1024
    return f"{size:.1f} TB"


def over_quota(root: Path, quotas_gb: dict[str, float]) -> list[str]:
    """Shows using more of the cache than their quota."""
    usage = usage_by_show(root)
    return [show for show, used in usage.items() if used > quotas_gb.get(show, float("inf")) * 1024**3]


def weekly_table(root: Path) -> str:
    rows = [f"{show:<20} {human(size):>10}" for show, size in usage_by_show(root).items()]
    return "\n".join(["show                       size", *rows]) + "\n"

