"""Quotes for replacement windows: glass by area, frame by perimeter, fitting per unit."""

from __future__ import annotations

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

from .glass import GLASS

FRAME_PER_METRE = {"upvc": Decimal("38.00"), "timber": Decimal("64.00"), "aluminium": Decimal("71.00")}
FITTING = Decimal("85.00")
VAT = Decimal("0.20")
PENNY = Decimal("0.01")


@dataclass(frozen=True)
class Window:
    width_mm: int
    height_mm: int
    glass: str = "double"
    frame: str = "upvc"


def window_price(window: Window) -> Decimal:
    if window.width_mm <= 0 or window.height_mm <= 0:
        raise ValueError("window sizes must be positive")
    area = Decimal(window.width_mm * window.height_mm) / Decimal(1_000_000)
    perimeter = Decimal(2 * (window.width_mm + window.height_mm)) / Decimal(1000)
    price = area * GLASS[window.glass] + perimeter * FRAME_PER_METRE[window.frame] + FITTING
    return price.quantize(PENNY, ROUND_HALF_UP)


def quote_total(windows: list[Window]) -> dict[str, Decimal]:
    net = sum((window_price(w) for w in windows), Decimal("0.00"))
    vat = (net * VAT).quantize(PENNY, ROUND_HALF_UP)
    return {"net": net, "vat": vat, "total": net + vat}

