// Booster schedules for the practice's patients (dogs and cats): when each vaccine is next due.
export type Species = "dog" | "cat";

const INTERVAL_DAYS: Record<Species, Record<string, number>> = {
  dog: { rabies: 1095, distemper: 1095, leptospirosis: 365, kennelCough: 365 },
  cat: { rabies: 1095, panleukopenia: 1095, calicivirus: 365 },
};

export function nextDue(species: Species, vaccine: string, lastGiven: string): string {
  const days = INTERVAL_DAYS[species][vaccine];
  if (days === undefined) throw new Error(`no schedule for ${vaccine} in ${species}s`);
  const due = new Date(`${lastGiven}T00:00:00Z`);
  due.setUTCDate(due.getUTCDate() + days);
  return due.toISOString().slice(0, 10);
}

export function overdue(species: Species, history: Record<string, string>, today: string): string[] {
  return Object.entries(history)
    .filter(([vaccine, last]) => nextDue(species, vaccine, last) < today)
    .map(([vaccine]) => vaccine)
    .sort();
}

