// Reminder letters for owners whose pets are due or overdue a booster.
import { nextDue, overdue } from "./vaccines.ts";
import type { Patient } from "./records.ts";

export interface Reminder {
  owner: string;
  patient: string;
  lines: string[];
}

export function remindersFor(patients: Patient[], today: string, horizonDays = 30): Reminder[] {
  const horizon = new Date(`${today}T00:00:00Z`);
  horizon.setUTCDate(horizon.getUTCDate() + horizonDays);
  const until = horizon.toISOString().slice(0, 10);
  const reminders: Reminder[] = [];
  for (const p of patients) {
    const late = overdue(p.species, p.vaccines, today);
    const soon = Object.entries(p.vaccines)
      .map(([vaccine, last]) => ({ vaccine, due: nextDue(p.species, vaccine, last) }))
      .filter(({ due }) => due >= today && due <= until);
    const lines = [
      ...late.map((v) => `${v}: overdue, please book an appointment`),
      ...soon.map(({ vaccine, due }) => `${vaccine}: due on ${due}`),
    ];
    if (lines.length > 0) reminders.push({ owner: p.owner, patient: p.name, lines });
  }
  return reminders;
}


export function letterText(reminder: Reminder, practice = "Brookside Veterinary Practice"): string {
  return [
    `Dear ${reminder.owner},`,
    "",
    `${reminder.patient} is due some vaccinations:`,
    ...reminder.lines.map((line) => `  - ${line}`),
    "",
    `Please call ${practice} to book.`,
  ].join("\n");
}

