from __future__ import annotations

from datetime import date

FROSTS = {
    "north-field": ((5, 12), (10, 8)),
    "river-meadow": ((5, 2), (10, 20)),
    "chapel-lane": ((4, 28), (10, 25)),
}


def last_frost(site: str, year: int) -> date:
    month, day = FROSTS[site][0]
    return date(year, month, day)


def first_frost(site: str, year: int) -> date:
    month, day = FROSTS[site][1]
    return date(year, month, day)

