"""When to sow, counted from the site's last frost."""

from __future__ import annotations

from datetime import date, timedelta

from .frost import first_frost, last_frost

# crop: (weeks after last frost to start sowing outdoors, weeks the window stays open, weeks to harvest)
CROPS = {
    "runner beans": (1, 6, 12),
    "courgettes": (2, 4, 10),
    "carrots": (-3, 12, 12),
    "peas": (-6, 10, 12),
}


def sowing_window(crop: str, site: str, year: int = 2026) -> tuple[date, date]:
    start_weeks, open_weeks, _ = CROPS[crop]
    start = last_frost(site, year) + timedelta(weeks=start_weeks)
    return start, start + timedelta(weeks=open_weeks)


def harvest_before_frost(crop: str, site: str, sown: date) -> bool:
    weeks_to_harvest = CROPS[crop][2]
    return sown + timedelta(weeks=weeks_to_harvest) <= first_frost(site, sown.year)

