"""Plot allocation: the waiting list, and who is offered a plot when one falls vacant."""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import date


@dataclass
class Site:
    name: str
    plots: dict[str, str | None]  # plot number -> holder, None when vacant
    waiting: list[tuple[date, str]] = field(default_factory=list)

    def join_waiting_list(self, person: str, joined: date) -> int:
        if any(p == person for _, p in self.waiting):
            raise ValueError(f"{person} is already waiting for a plot at {self.name}")
        self.waiting.append((joined, person))
        self.waiting.sort()
        return [p for _, p in self.waiting].index(person) + 1

    def give_up(self, plot: str) -> str | None:
        """Free a plot and offer it to whoever has waited longest."""
        if self.plots.get(plot) is None:
            raise ValueError(f"plot {plot} is not let")
        self.plots[plot] = None
        if not self.waiting:
            return None
        _, person = self.waiting.pop(0)
        self.plots[plot] = person
        return person

    def vacant(self) -> list[str]:
        return sorted(p for p, holder in self.plots.items() if holder is None)


def rent_due(site: Site, rate_per_plot: int = 45, concessions: set[str] | None = None) -> dict[str, int]:
    """Annual rent per holder; holders on a concession pay half."""
    concessions = concessions or set()
    due: dict[str, int] = {}
    for holder in site.plots.values():
        if holder is not None:
            due[holder] = due.get(holder, 0) + (rate_per_plot // 2 if holder in concessions else rate_per_plot)
    return dict(sorted(due.items()))


def waiting_days(site: Site, today: date) -> dict[str, int]:
    return {person: (today - joined).days for joined, person in site.waiting}

