// Web-Mercator tile maths: which z/x/y tiles cover a bounding box.
export interface Bounds {
  west: number;
  south: number;
  east: number;
  north: number;
}

export interface Tile {
  z: number;
  x: number;
  y: number;
}

export function tileFor(lon: number, lat: number, zoom: number): { x: number; y: number } {
  const n = 2 ** zoom;
  const x = Math.floor(((lon + 180) / 360) * n);
  const rad = (lat * Math.PI) / 180;
  const y = Math.floor(((1 - Math.log(Math.tan(rad) + 1 / Math.cos(rad)) / Math.PI) / 2) * n);
  return { x: Math.min(n - 1, Math.max(0, x)), y: Math.min(n - 1, Math.max(0, y)) };
}

export function tilesCovering(bounds: Bounds, zoom: number): Tile[] {
  const nw = tileFor(bounds.west, bounds.north, zoom);
  const se = tileFor(bounds.east, bounds.south, zoom);
  const tiles: Tile[] = [];
  for (let x = nw.x; x <= se.x; x++) for (let y = nw.y; y <= se.y; y++) tiles.push({ z: zoom, x, y });
  return tiles;
}

