// Pre-renders every tile of the county for zoom levels 8-15 into public/tiles/z/x/y.json.
import { mkdir, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { tilesCovering } from "./tiles.ts";
import type { Bounds } from "./tiles.ts";

export const COUNTY: Bounds = { west: -3.62, south: 54.04, east: -2.16, north: 54.97 };

export async function renderAll(bounds: Bounds, zooms: number[], outDir: string): Promise<number> {
  const rendered = zooms
    .flatMap((z) => tilesCovering(bounds, z))
    .map((t) => ({ dir: `${outDir}/${t.z}/${t.x}`, file: `${t.y}.json`, body: JSON.stringify({ ...t, features: [] }) }));
  for (const tile of rendered) {
    await mkdir(tile.dir, { recursive: true });
    await writeFile(`${tile.dir}/${tile.file}`, tile.body);
  }
  return rendered.length;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const count = await renderAll(COUNTY, [8, 9, 10, 11, 12, 13, 14, 15], "public/tiles");
  console.log(`rendered ${count} tiles`);
}

