// Footpath features for a tile: keep only the paths whose bounding box touches the tile.
import type { Bounds } from "./tiles.ts";

export interface Way {
  id: string;
  kind: "footpath" | "bridleway" | "byway";
  points: [number, number][]; // [lon, lat]
}

export function bboxOf(points: [number, number][]): Bounds {
  const lons = points.map((p) => p[0]);
  const lats = points.map((p) => p[1]);
  return { west: Math.min(...lons), south: Math.min(...lats), east: Math.max(...lons), north: Math.max(...lats) };
}

export function touches(a: Bounds, b: Bounds): boolean {
  return a.west <= b.east && b.west <= a.east && a.south <= b.north && b.south <= a.north;
}

export function waysForTile(ways: Way[], tile: Bounds): Way[] {
  return ways.filter((w) => w.points.length > 1 && touches(bboxOf(w.points), tile));
}

export function tileBounds(z: number, x: number, y: number): Bounds {
  const n = 2 ** z;
  const lon = (i: number) => (i / n) * 360 - 180;
  const lat = (j: number) => (Math.atan(Math.sinh(Math.PI * (1 - (2 * j) / n))) * 180) / Math.PI;
  return { west: lon(x), east: lon(x + 1), north: lat(y), south: lat(y + 1) };
}


export function simplifyForZoom(way: Way, zoom: number): Way {
  // Below zoom 12 the map only needs every few points of a path.
  const step = zoom >= 14 ? 1 : zoom >= 12 ? 2 : 4;
  return { ...way, points: way.points.filter((_, i) => i % step === 0 || i === way.points.length - 1) };
}

export function tileFeatures(ways: Way[], z: number, x: number, y: number): Way[] {
  return waysForTile(ways, tileBounds(z, x, y)).map((w) => simplifyForZoom(w, z));
}

export function lengthKm(way: Way): number {
  let km = 0;
  for (let i = 1; i < way.points.length; i++) {
    const [lon1, lat1] = way.points[i - 1];
    const [lon2, lat2] = way.points[i];
    const dx = (lon2 - lon1) * 111.32 * Math.cos((((lat1 + lat2) / 2) * Math.PI) / 180);
    km += Math.hypot(dx, (lat2 - lat1) * 110.57);
  }
  return Math.round(km * 100) / 100;
}

