"""Berth bookings: a berth is free for a stay if no booking overlaps it and the boat fits."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import date


@dataclass(frozen=True)
class Booking:
    berth: str
    boat: str
    arrive: date
    depart: date


def overlaps(booking: Booking, arrive: date, depart: date) -> bool:
    return booking.arrive < depart and arrive < booking.depart


def free_berths(berths: list[str], bookings: list[Booking], arrive: date, depart: date,
                length_m: float, max_length: dict[str, float]) -> list[str]:
    if depart <= arrive:
        raise ValueError("departure must be after arrival")
    taken = {b.berth for b in bookings if overlaps(b, arrive, depart)}
    return [berth for berth in berths if berth not in taken and max_length[berth] >= length_m]

