"""Berth fees: per metre of boat length per night, dearer in summer; every seventh night is free."""

from __future__ import annotations

from datetime import date, timedelta
from decimal import ROUND_HALF_UP, Decimal

WINTER_PER_METRE = Decimal("1.60")
SUMMER_PER_METRE = Decimal("2.85")


def is_summer(night: date) -> bool:
    return date(night.year, 5, 1) <= night <= date(night.year, 9, 30)


def stay_fee(length_m: float, arrive: date, depart: date) -> Decimal:
    if depart <= arrive:
        raise ValueError("departure must be after arrival")
    nights = [arrive + timedelta(days=i) for i in range((depart - arrive).days)]
    free = len(nights) // 7
    charged = sorted(nights, key=is_summer)[free:]  # free nights come off the cheaper end
    metres = Decimal(str(length_m))
    total = sum((metres * (SUMMER_PER_METRE if is_summer(n) else WINTER_PER_METRE) for n in charged), Decimal("0"))
    return total.quantize(Decimal("0.01"), ROUND_HALF_UP)


def electricity_charge(kwh: float, rate: Decimal = Decimal("0.34")) -> Decimal:
    return (Decimal(str(kwh)) * rate).quantize(Decimal("0.01"), ROUND_HALF_UP)


def invoice_lines(boat: str, length_m: float, arrive: date, depart: date, kwh: float = 0.0) -> list[str]:
    berth = stay_fee(length_m, arrive, depart)
    power = electricity_charge(kwh)
    lines = [f"{boat} ({length_m} m), {(depart - arrive).days} nights from {arrive:%d %b}", f"Berth: {berth}"]
    if kwh:
        lines.append(f"Electricity ({kwh} kWh): {power}")
    lines.append(f"Total: {berth + power}")
    return lines

