"""The canteen's weekly menu and its allergen labels."""

from __future__ import annotations

from dataclasses import dataclass, field

ALLERGENS = {"gluten", "milk", "egg", "nuts", "peanuts", "soya", "fish", "sesame", "celery", "mustard"}


@dataclass(frozen=True)
class Dish:
    name: str
    allergens: frozenset[str] = field(default_factory=frozenset)
    vegetarian: bool = False

    def __post_init__(self) -> None:
        unknown = set(self.allergens) - ALLERGENS
        if unknown:
            raise ValueError(f"{self.name}: unknown allergens {sorted(unknown)}")


def safe_for(dishes: list[Dish], avoid: set[str]) -> list[Dish]:
    return [d for d in dishes if not (d.allergens & avoid)]


def label(dish: Dish) -> str:
    tags = sorted(dish.allergens)
    name = f"{dish.name} (V)" if dish.vegetarian else dish.name
    return f"{name} - contains {', '.join(tags)}" if tags else name

