"""Pre-orders: each class sends its lunch choices by 10:00 so the kitchen knows how much to cook."""

from __future__ import annotations

from collections import Counter
from datetime import datetime, time

CUTOFF = time(10, 0)


def accept_order(classroom: str, choices: dict[str, str], received: datetime, menu: list[str]) -> Counter:
    """Count a class's choices (pupil -> dish). Late orders and dishes not on the menu are refused."""
    if received.time() > CUTOFF:
        raise ValueError(f"{classroom}: orders close at {CUTOFF:%H:%M}")
    unknown = sorted({dish for dish in choices.values() if dish not in menu})
    if unknown:
        raise ValueError(f"{classroom}: not on today's menu: {', '.join(unknown)}")
    return Counter(choices.values())


def kitchen_totals(orders: list[Counter]) -> list[tuple[str, int]]:
    total: Counter = Counter()
    for order in orders:
        total.update(order)
    return total.most_common()

