// Decoding the turnstile scanners' reads: "RW|<ticketId>|<zone>|<validFrom>|<validTo>|<check>".
export interface Scan {
  ticketId: string;
  zone: string;
  validFrom: string;
  validTo: string;
}

export function checksum(text: string): string {
  let sum = 0;
  for (const ch of text) sum = (sum * 31 + ch.charCodeAt(0)) % 9973;
  return String(sum).padStart(4, "0");
}

export function decodeScan(raw: string): Scan {
  const parts = raw.trim().split("|");
  if (parts[0] !== "RW") throw new Error("not a ropeway ticket");
  if (checksum(parts.slice(0, 5).join("|")) !== parts[5]) throw new Error("bad checksum");
  return { ticketId: parts[1], zone: parts[2], validFrom: parts[3], validTo: parts[4] };
}

export function lastScans(buffer: string[], count: number): string[] {
  const out: string[] = [];
  for (let i = buffer.length - count; i < buffer.length; i++) out.push(buffer[i].trim());
  return out;
}

