// Whether a decoded ticket admits its holder to a zone at a given time.
import type { Scan } from "./scanner.ts";

export function admits(scan: Scan, zone: string, at: string): boolean {
  return (scan.zone === zone || scan.zone === "ALL") && scan.validFrom <= at && at <= scan.validTo;
}

