// Fares for the cable car: by zone and age group, with a family ticket.
export type AgeGroup = "adult" | "child" | "senior";

const FARES: Record<string, Record<AgeGroup, number>> = {
  MIDDLE: { adult: 18, child: 9, senior: 14 },
  SUMMIT: { adult: 29, child: 14.5, senior: 23 },
  ALL: { adult: 34, child: 17, senior: 27 },
};

export function fare(zone: string, group: AgeGroup): number {
  const table = FARES[zone];
  if (!table) throw new Error(`no fares for zone ${zone}`);
  return table[group];
}

export function partyFare(zone: string, party: AgeGroup[]): number {
  const single = party.reduce((sum, g) => sum + fare(zone, g), 0);
  const adults = party.filter((g) => g === "adult").length;
  const children = party.filter((g) => g === "child").length;
  if (adults === 2 && children >= 1 && children <= 3 && party.length === adults + children) {
    return Math.min(single, fare(zone, "adult") * 2 + fare(zone, "child"));
  }
  return single;
}


export function groupDiscount(total: number, people: number): number {
  if (people >= 20) return Math.round(total * 0.85 * 100) / 100;
  if (people >= 10) return Math.round(total * 0.9 * 100) / 100;
  return total;
}

export function zonesFor(stop: string): string[] {
  if (stop === "middle") return ["MIDDLE", "SUMMIT", "ALL"];
  return stop === "summit" ? ["SUMMIT", "ALL"] : ["ALL"];
}

