"""Melt planning: furnace charges of a single alloy, within the furnace's capacity."""

from __future__ import annotations

from collections import defaultdict

from .jobs import Job

KG_PER_CASTING = {"LM6": 2.4, "LM25": 3.1, "CuSn10": 5.6}


def charges(jobs: list[Job], furnace_kg: float = 250.0) -> list[tuple[str, list[str], float]]:
    by_alloy: dict[str, list[Job]] = defaultdict(list)
    for job in jobs:
        if job.stage in ("moulding", "melting"):
            by_alloy[job.alloy].append(job)
    plan = []
    for alloy in sorted(by_alloy):
        batch: list[str] = []
        weight = 0.0
        for job in by_alloy[alloy]:
            kg = job.castings * KG_PER_CASTING[alloy]
            if batch and weight + kg > furnace_kg:
                plan.append((alloy, batch, round(weight, 1)))
                batch, weight = [], 0.0
            batch.append(job.number)
            weight += kg
        plan.append((alloy, batch, round(weight, 1)))
    return plan

