"""Inspection results for finished castings: defects found, and scrap rates per pattern or alloy."""

from __future__ import annotations

from collections import Counter, defaultdict
from dataclasses import dataclass

DEFECTS = ("porosity", "cold shut", "misrun", "inclusion", "shrinkage", "dimensional")


@dataclass(frozen=True)
class Inspection:
    job: str
    pattern: str
    alloy: str
    inspected: int
    rejected: int
    defects: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if self.rejected > self.inspected:
            raise ValueError(f"{self.job}: more rejected than inspected")
        unknown = set(self.defects) - set(DEFECTS)
        if unknown:
            raise ValueError(f"{self.job}: unknown defect {sorted(unknown)}")


def scrap_rate(inspections: list[Inspection], key: str = "pattern") -> dict[str, float]:
    inspected: dict[str, int] = defaultdict(int)
    rejected: dict[str, int] = defaultdict(int)
    for i in inspections:
        group = getattr(i, key)
        inspected[group] += i.inspected
        rejected[group] += i.rejected
    return {g: round(100 * rejected[g] / inspected[g], 1) for g in sorted(inspected) if inspected[g]}


def top_defects(inspections: list[Inspection], count: int = 3) -> list[tuple[str, int]]:
    return Counter(d for i in inspections for d in i.defects).most_common(count)

