// Release notes from commit subjects written as "type(scope): summary".
export interface Commit {
  hash: string;
  subject: string;
}

const SECTIONS: Record<string, string> = { feat: "Features", fix: "Fixes", perf: "Performance", docs: "Documentation" };

export function releaseNotes(version: string, commits: Commit[]): string {
  const groups = new Map<string, string[]>();
  for (const commit of commits) {
    const match = /^(\w+)(?:\(([^)]+)\))?!?: (.+)$/.exec(commit.subject);
    const section = match ? SECTIONS[match[1]] : undefined;
    if (!match || !section) continue;
    const scope = match[2] ? `**${match[2]}:** ` : "";
    groups.set(section, [...(groups.get(section) ?? []), `- ${scope}${match[3]} (${commit.hash.slice(0, 7)})`]);
  }
  const parts = [`## ${version}`];
  for (const section of Object.values(SECTIONS)) {
    const lines = groups.get(section);
    if (lines) parts.push("", `### ${section}`, ...lines);
  }
  return parts.join("\n") + "\n";
}

