// Reading tags and commits with the git command line.
import { execFileSync } from "node:child_process";
import type { Commit } from "./notes.ts";

export function previousTag(ref = "HEAD"): string | undefined {
  try {
    return execFileSync("git", ["describe", "--tags", "--abbrev=0", `${ref}^`], { encoding: "utf8" }).trim();
  } catch {
    return undefined;
  }
}

export function commitsSince(tag: string | undefined): Commit[] {
  const range = tag ? `${tag}..HEAD` : "HEAD";
  const out = execFileSync("git", ["log", "--format=%H%x09%s", range], { encoding: "utf8" });
  return out
    .trim()
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      const [hash, subject] = line.split("\t");
      return { hash, subject };
    });
}

