// Version numbers for releases: which part to bump, given the commits since the last tag.
import type { Commit } from "./notes.ts";

export function parseVersion(tag: string): [number, number, number] {
  const match = /^v?(\d+)\.(\d+)\.(\d+)$/.exec(tag);
  if (!match) throw new Error(`not a version tag: ${tag}`);
  return [Number(match[1]), Number(match[2]), Number(match[3])];
}

export function nextVersion(previous: string, commits: Commit[]): string {
  const [major, minor, patch] = parseVersion(previous);
  const breaking = commits.some((c) => /^\w+(\([^)]+\))?!:/.test(c.subject) || c.subject.includes("BREAKING CHANGE"));
  if (breaking) return `v${major + 1}.0.0`;
  if (commits.some((c) => c.subject.startsWith("feat"))) return `v${major}.${minor + 1}.0`;
  return `v${major}.${minor}.${patch + 1}`;
}


export function compareVersions(a: string, b: string): number {
  const [x, y] = [parseVersion(a), parseVersion(b)];
  for (let i = 0; i < 3; i++) if (x[i] !== y[i]) return x[i] - y[i];
  return 0;
}

export function latestTag(tags: string[]): string | undefined {
  return tags.filter((t) => /^v\d+\.\d+\.\d+$/.test(t)).sort(compareVersions).at(-1);
}

export function changelogEntry(version: string, date: string, notes: string): string {
  const body = notes.split("\n").slice(1).join("\n").trim();
  return `## ${version} (${date})\n\n${body}\n`;
}

