"""Bookings for the hedge-laying weekend courses: places, waiting list and kit hire."""

from __future__ import annotations

from dataclasses import dataclass, field

KIT_HIRE = 12  # pounds per weekend: billhook, gloves, stakes


@dataclass
class Course:
    code: str
    places: int
    booked: list[str] = field(default_factory=list)
    waiting: list[str] = field(default_factory=list)
    kit: set[str] = field(default_factory=set)

    def book(self, person: str, hire_kit: bool = False) -> str:
        if person in self.booked or person in self.waiting:
            raise ValueError(f"{person} already booked on {self.code}")
        if len(self.booked) < self.places:
            self.booked.append(person)
            if hire_kit:
                self.kit.add(person)
            return "booked"
        self.waiting.append(person)
        return "waiting"

    def cancel(self, person: str) -> None:
        if person in self.waiting:
            self.waiting.remove(person)
            return
        self.booked.remove(person)
        self.kit.discard(person)
        if self.waiting:
            self.booked.append(self.waiting.pop(0))

    def kit_income(self) -> int:
        return KIT_HIRE * len(self.kit)

