"""Estimating a hedge-laying job: stakes and binders, and how many days a team needs."""

from __future__ import annotations

import math
from dataclasses import dataclass

STAKE_SPACING_M = 0.45
BINDERS_PER_METRE = 4  # hazel binders woven along the top
METRES_PER_PERSON_DAY = {"midland": 8, "south of england": 10, "welsh border": 7}


@dataclass(frozen=True)
class HedgeJob:
    length_m: float
    style: str
    people: int

    def stakes(self) -> int:
        return math.ceil(self.length_m / STAKE_SPACING_M) + 1

    def binders(self) -> int:
        return math.ceil(self.length_m * BINDERS_PER_METRE)

    def days(self) -> float:
        rate = METRES_PER_PERSON_DAY.get(self.style)
        if rate is None:
            raise ValueError(f"unknown hedge style {self.style!r}")
        if self.people < 1:
            raise ValueError("a job needs at least one person")
        return round(self.length_m / (rate * self.people), 1)


def quote(job: HedgeJob, day_rate: int = 160, stake_price: float = 0.85, binder_price: float = 0.4) -> dict[str, float]:
    labour = job.days() * job.people * day_rate
    materials = job.stakes() * stake_price + job.binders() * binder_price
    return {"labour": round(labour, 2), "materials": round(materials, 2), "total": round(labour + materials, 2)}


def season_ok(month: int) -> bool:
    """Hedges are laid between October and March, outside the nesting season."""
    return month >= 10 or month <= 3

