"""The lighting column register: column ids, the street each stands on, and survey routes."""

from __future__ import annotations

import re
from dataclasses import dataclass

COLUMN_ID = re.compile(r"^LC-\d{4}$")


@dataclass(frozen=True)
class Column:
    column_id: str
    street: str
    house_near: str
    lantern: str  # "led", "sodium" or "heritage"

    def __post_init__(self) -> None:
        if not COLUMN_ID.match(self.column_id):
            raise ValueError(f"bad column id {self.column_id!r}")


def survey_route(columns: list[Column], streets: list[str]) -> list[Column]:
    """The columns to check on a night-time survey, street by street in the given order."""
    order = {street: i for i, street in enumerate(streets)}
    on_route = [c for c in columns if c.street in order]
    return sorted(on_route, key=lambda c: (order[c.street], c.column_id))


def heritage_columns(columns: list[Column]) -> list[str]:
    return sorted(c.column_id for c in columns if c.lantern == "heritage")


def faults_by_street(faults: list[tuple[str, str]], columns: list[Column]) -> dict[str, int]:
    """Reported faults per street, from (column id, fault type) pairs."""
    street_of = {c.column_id: c.street for c in columns}
    counts: dict[str, int] = {}
    for column_id, _ in faults:
        street = street_of.get(column_id, "unknown street")
        counts[street] = counts.get(street, 0) + 1
    return dict(sorted(counts.items(), key=lambda kv: (-kv[1], kv[0])))


def repeat_faults(faults: list[tuple[str, str]], times: int = 3) -> list[str]:
    seen: dict[str, int] = {}
    for column_id, _ in faults:
        seen[column_id] = seen.get(column_id, 0) + 1
    return sorted(c for c, n in seen.items() if n >= times)

