// Boat hire pricing: hourly rate per boat type, at least one hour, capped at the half-day price.
export const RATES: Record<string, { hourly: number; halfDay: number }> = {
  rowing: { hourly: 18, halfDay: 55 },
  kayak: { hourly: 14, halfDay: 40 },
  motor: { hourly: 45, halfDay: 150 },
};

export function hirePrice(boat: string, minutes: number): number {
  const rate = RATES[boat];
  if (!rate) throw new Error(`no such boat type: ${boat}`);
  if (minutes <= 0) throw new Error("hire must be at least one minute");
  const hours = Math.max(1, Math.ceil(minutes / 60));
  return hours >= 4 ? rate.halfDay : Math.min(rate.halfDay, hours * rate.hourly);
}

