repo.src/weather.ts:
// Lake closures: hire stops when the wind is too strong for the boat type, and always for lightning.
export interface Forecast {
  hour: number;
  windKnots: number;
  gustKnots: number;
  lightning: boolean;
}

const LIMITS: Record<string, number> = { rowing: 18, kayak: 15, motor: 22 };

export function openHours(boat: string, forecast: Forecast[]): number[] {
  const limit = LIMITS[boat];
  if (limit === undefined) throw new Error(`no wind limit for ${boat}`);
  return forecast
    .filter((f) => !f.lightning && f.windKnots <= limit && f.gustKnots <= limit + 8)
    .map((f) => f.hour)
    .sort((a, b) => a - b);
}

export function closureNotice(boat: string, forecast: Forecast[]): string | undefined {
  const open = new Set(openHours(boat, forecast));
  const closed = forecast.map((f) => f.hour).filter((h) => !open.has(h));
  if (closed.length === 0) return undefined;
  return `${boat} hire closed ${closed.map((h) => `${String(h).padStart(2, "0")}:00`).join(", ")} (weather)`;
}

