"""The ringing register: every bird ringed at the observatory, and later recaptures."""

from __future__ import annotations

import re
from dataclasses import dataclass, field

RING = re.compile(r"^[A-Z]{1,2}\d{4,6}$")


@dataclass
class RingRegister:
    records: dict[str, dict] = field(default_factory=dict)

    def ring(self, ring: str, species: str, date: str, site: str) -> None:
        if not RING.match(ring):
            raise ValueError(f"malformed ring number {ring!r}")
        if ring in self.records:
            raise ValueError(f"ring {ring} is already on a bird")
        self.records[ring] = {"ring": ring, "species": species, "ringed": date, "site": site, "recaptures": []}

    def recapture(self, ring: str, date: str, site: str) -> int:
        record = self.records[ring]
        record["recaptures"].append({"date": date, "site": site})
        return len(record["recaptures"])

    def lookup(self, ring: str) -> dict | None:
        return self.records.get(ring)

