"""Species and the ring size each one takes."""

from __future__ import annotations

RING_SIZES = {
    "Wren": "AA",
    "Blue Tit": "A",
    "Sedge Warbler": "A",
    "Robin": "AB",
    "Blackbird": "C",
    "Starling": "C",
    "Sparrowhawk": "D",
    "Mallard": "F",
}


def ring_size(species: str) -> str:
    try:
        return RING_SIZES[species]
    except KeyError:
        raise ValueError(f"no ring size on record for {species}") from None


def check_ring(species: str, ring: str) -> bool:
    """Ring numbers carry their size as a prefix, e.g. AB12345 for a Robin."""
    size = ring_size(species)
    return ring[: len(size)] == size and ring[len(size):].isdigit()


def species_counts(records: list[dict]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for record in records:
        counts[record["species"]] = counts.get(record["species"], 0) + 1
    return dict(sorted(counts.items(), key=lambda kv: (-kv[1], kv[0])))


def ringing_totals(records: list[dict], year: int) -> dict[str, dict[str, int]]:
    """New birds ringed and recaptures per species for one year."""
    totals: dict[str, dict[str, int]] = {}
    for record in records:
        species = totals.setdefault(record["species"], {"new": 0, "recaptured": 0})
        if record["ringed"].startswith(str(year)):
            species["new"] += 1
        species["recaptured"] += sum(1 for r in record["recaptures"] if r["date"].startswith(str(year)))
    return dict(sorted(totals.items()))


def longest_interval_days(record: dict) -> int:
    """Days between ringing and the latest recapture, for the longevity notes."""
    from datetime import date

    if not record["recaptures"]:
        return 0
    last = max(date.fromisoformat(r["date"]) for r in record["recaptures"])
    return (last - date.fromisoformat(record["ringed"])).days

