"""Tile colours in stock, and the nearest colour to use when one runs short."""

from __future__ import annotations

STOCK = {
    "A": ("cobalt", (31, 78, 121), 1200),
    "B": ("bone", (230, 230, 220), 3400),
    "C": ("terracotta", (190, 120, 60), 800),
    "D": ("sage", (150, 170, 140), 950),
}


def distance(a: tuple[int, int, int], b: tuple[int, int, int]) -> int:
    return sum((x - y) ** 2 for x, y in zip(a, b))


def substitute(code: str, needed: int) -> str:
    """The colour to use for ``needed`` tiles of ``code``: itself if in stock, else the nearest one that is."""
    name, rgb, count = STOCK[code]
    if count >= needed:
        return code
    options = [(distance(rgb, other_rgb), other) for other, (_, other_rgb, n) in STOCK.items()
               if other != code and n >= needed]
    if not options:
        raise ValueError(f"not enough {name} tiles and no close substitute in stock")
    return min(options)[1]


def reserve(code: str, tiles: int) -> int:
    """Take tiles out of stock for a job; returns what is left."""
    name, rgb, count = STOCK[code]
    if tiles > count:
        raise ValueError(f"only {count} {name} tiles left")
    STOCK[code] = (name, rgb, count - tiles)
    return count - tiles


def colours_for(pattern: list[str]) -> dict[str, int]:
    """How many cells of each colour code one repeat of a pattern uses."""
    counts: dict[str, int] = {}
    for row in pattern:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1
    return dict(sorted(counts.items()))

