// Fabric needed for a garment: the layout's base length, more on narrow fabric or for directional prints.
const BASE_CM: Record<string, Record<string, number>> = {
  dress: { XS: 210, S: 220, M: 230, L: 245, XL: 260 },
  skirt: { XS: 90, S: 95, M: 100, L: 110, XL: 120 },
};

export function fabricNeeded(garment: string, size: string, widthCm: 115 | 150, directional = false): number {
  const base = BASE_CM[garment]?.[size];
  if (base === undefined) throw new Error(`no layout for ${garment} in ${size}`);
  const narrow = widthCm === 115 ? 1.3 : 1;
  const extra = directional ? 1.15 : 1;
  return Math.ceil((base * narrow * extra) / 10) * 10;
}

