// Haberdashery for a pattern: zips, buttons and interfacing by garment and size.
export interface Notions {
  zipCm?: number;
  buttons?: number;
  interfacingCm: number;
}

const NOTIONS: Record<string, (size: string) => Notions> = {
  dress: (size) => ({ zipCm: ["L", "XL"].includes(size) ? 60 : 55, interfacingCm: 30 }),
  skirt: () => ({ zipCm: 20, buttons: 1, interfacingCm: 15 }),
  shirt: (size) => ({ buttons: ["XS", "S"].includes(size) ? 7 : 8, interfacingCm: 50 }),
};

export function notionsFor(garment: string, size: string): Notions {
  const rule = NOTIONS[garment];
  if (!rule) throw new Error(`no notions list for ${garment}`);
  return rule(size);
}

export function shoppingList(items: { garment: string; size: string }[]): string[] {
  let zips = 0;
  let buttons = 0;
  let interfacing = 0;
  for (const { garment, size } of items) {
    const n = notionsFor(garment, size);
    if (n.zipCm) zips++;
    buttons += n.buttons ?? 0;
    interfacing += n.interfacingCm;
  }
