"""Recording feedings and adding them up."""

from __future__ import annotations

import sqlite3


def record_feed(conn: sqlite3.Connection, day: str, pen: str, feed: str, kg: float) -> None:
    with conn:
        conn.execute("INSERT INTO feedings (day, pen, feed, kg) VALUES (?, ?, ?, ?)", (day, pen, feed, kg))


def totals_by_feed(conn: sqlite3.Connection, start: str, end: str) -> dict[str, float]:
    rows = conn.execute(
        "SELECT feed, ROUND(SUM(kg), 1) FROM feedings WHERE day BETWEEN ? AND ? GROUP BY feed ORDER BY feed",
        (start, end),
    )
    return dict(rows.fetchall())

