"""Daily rations per pen: hay by body weight, plus ewe nuts in the last weeks before lambing."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class Pen:
    name: str
    head: int
    mean_weight_kg: float
    weeks_to_lambing: int | None = None


def hay_kg(pen: Pen) -> float:
    """Dry matter at 2% of body weight a day, fed as hay at 85% dry matter."""
    return round(pen.head * pen.mean_weight_kg * 0.02 / 0.85, 1)


def concentrate_kg(pen: Pen) -> float:
    if pen.weeks_to_lambing is None or pen.weeks_to_lambing > 6:
        return 0.0
    per_ewe = 0.25 if pen.weeks_to_lambing > 3 else 0.5
    return round(pen.head * per_ewe, 1)


def daily_sheet(pens: list[Pen]) -> list[str]:
    return [f"{p.name:12} hay {hay_kg(p):6.1f} kg   nuts {concentrate_kg(p):5.1f} kg" for p in pens]


def weekly_order(pens: list[Pen], bale_kg: float = 20.0, bag_kg: float = 25.0) -> dict[str, int]:
    """Bales of hay and bags of ewe nuts for the coming week."""
    hay = sum(hay_kg(p) for p in pens) * 7
    nuts = sum(concentrate_kg(p) for p in pens) * 7
    return {"bales": int(-(-hay // bale_kg)), "bags": int(-(-nuts // bag_kg))}

