// Daily and monthly inspections of the ski lifts: what is due and whether a lift may open.
export interface Inspection {
  lift: string;
  kind: "daily" | "monthly";
  date: string;
  passed: boolean;
  notes?: string;
}

const EVERY_DAYS = { daily: 1, monthly: 30 };

export function nextDue(history: Inspection[], kind: "daily" | "monthly", today: string): string {
  const last = history.filter((i) => i.kind === kind && i.passed).map((i) => i.date).sort().at(-1);
  if (!last) return today;
  const due = new Date(`${last}T00:00:00Z`);
  due.setUTCDate(due.getUTCDate() + EVERY_DAYS[kind]);
  const iso = due.toISOString().slice(0, 10);
  return iso < today ? today : iso;
}

export function mayOpen(history: Inspection[], today: string): boolean {
  return nextDue(history, "daily", today) > today && nextDue(history, "monthly", today) > today;
}

