// Lift staffing: every open lift needs an operator at the bottom, and chairlifts and gondolas one at the top.
export interface LiftPlan {
  lift: string;
  kind: "chair" | "drag" | "gondola";
  open: boolean;
}

export interface Rostered {
  name: string;
  qualified: string[];
}

type Post = { lift: string; post: "bottom" | "top" };

export function postsNeeded(plans: LiftPlan[]): Post[] {
  const posts: Post[] = [];
  for (const plan of plans.filter((p) => p.open)) {
    posts.push({ lift: plan.lift, post: "bottom" });
    if (plan.kind !== "drag") posts.push({ lift: plan.lift, post: "top" });
  }
  return posts;
}

export function allocate(plans: LiftPlan[], staff: Rostered[]): { filled: Record<string, string>; unfilled: string[] } {
  const filled: Record<string, string> = {};
  const unfilled: string[] = [];
  const free = [...staff];
  for (const { lift, post } of postsNeeded(plans)) {
    const index = free.findIndex((s) => s.qualified.includes(lift));
    if (index < 0) unfilled.push(`${lift} ${post}`);
    else filled[`${lift} ${post}`] = free.splice(index, 1)[0].name;
  }
  return { filled, unfilled };
}

