"""The household ledger: one CSV, appended to by each import, never holding a transaction twice."""

from __future__ import annotations

import csv
from pathlib import Path

from .statements import Transaction


def existing(path: Path) -> set[tuple[str, str, str]]:
    if not path.exists():
        return set()
    with open(path, newline="", encoding="utf-8") as handle:
        return {(r["day"], r["amount"], r["text"]) for r in csv.DictReader(handle)}


def append(path: Path, transactions: list[Transaction]) -> int:
    seen = existing(path)
    fresh = [t for t in transactions if (t.day.isoformat(), str(t.amount), t.text) not in seen]
    new_file = not path.exists()
    with open(path, "a", newline="", encoding="utf-8") as handle:
        writer = csv.writer(handle)
        if new_file:
            writer.writerow(["day", "amount", "text"])
        for t in fresh:
            writer.writerow([t.day.isoformat(), str(t.amount), t.text])
    return len(fresh)

