"""Monthly budget check: spending per category against the household budget."""

from __future__ import annotations

from collections import defaultdict
from decimal import Decimal

from .statements import Transaction

BUDGET = {"groceries": Decimal("450"), "energy": Decimal("180"), "transport": Decimal("120"), "eating out": Decimal("90")}

KEYWORDS = {
    "groceries": ("market", "grocer", "bakery", "corner shop"),
    "energy": ("electric", "gas", "heating oil"),
    "transport": ("rail", "bus", "fuel", "parking"),
    "eating out": ("cafe", "restaurant", "takeaway", "pub"),
}


def category_of(t: Transaction) -> str:
    text = t.text.lower()
    for category, words in KEYWORDS.items():
        if any(w in text for w in words):
            return category
    return "other"


def spending(transactions: list[Transaction], month: str) -> dict[str, Decimal]:
    totals: dict[str, Decimal] = defaultdict(Decimal)
    for t in transactions:
        if t.day.isoformat().startswith(month) and t.amount < 0:
            totals[category_of(t)] += -t.amount
    return dict(sorted(totals.items()))


def over_budget(transactions: list[Transaction], month: str) -> list[str]:
    report = []
    for category, spent in spending(transactions, month).items():
        limit = BUDGET.get(category)
        if limit is not None and spent > limit:
            report.append(f"{category}: {spent} spent, budget {limit} (over by {spent - limit})")
    return report

