repo.src/promotions.ts:
// Multibuy offers at the till: "3 for 2" style and "2 for a fixed price", applied per product.
export type Offer = { kind: "x-for-y"; buy: number; pay: number } | { kind: "fixed"; quantity: number; price: number };

export function lineTotal(unitPrice: number, quantity: number, offer?: Offer): number {
  const cents = Math.round(unitPrice * 100);
  if (!offer) return (cents * quantity) / 100;
  if (offer.kind === "x-for-y") {
    const groups = Math.floor(quantity / offer.buy);
    return (groups * offer.pay * cents + (quantity % offer.buy) * cents) / 100;
  }
  const groups = Math.floor(quantity / offer.quantity);
  return (groups * Math.round(offer.price * 100) + (quantity % offer.quantity) * cents) / 100;
}

export function saving(unitPrice: number, quantity: number, offer: Offer): number {
  return Math.round((unitPrice * quantity - lineTotal(unitPrice, quantity, offer)) * 100) / 100;
}


export interface BasketLine {
  product: string;
  unitPrice: number;
  quantity: number;
}

export function basketTotal(lines: BasketLine[], offers: Record<string, Offer>): { total: number; saved: number } {
  let total = 0;
  let saved = 0;
  for (const line of lines) {
    const offer = offers[line.product];
    total += lineTotal(line.unitPrice, line.quantity, offer);
    if (offer) saved += saving(line.unitPrice, line.quantity, offer);
  }
  return { total: Math.round(total * 100) / 100, saved: Math.round(saved * 100) / 100 };
}

export function describeOffer(offer: Offer): string {
  return offer.kind === "x-for-y" ? `${offer.buy} for ${offer.pay}` : `${offer.quantity} for ${offer.price.toFixed(2)}`;
}

