repo.src/tillroll/vat.py:
"""VAT in the cafe's takings: eat-in food and drinks are standard rated, cold take-away is zero rated."""

from __future__ import annotations

from decimal import ROUND_HALF_UP, Decimal

RATES = {"standard": Decimal("0.20"), "zero": Decimal("0")}
CATEGORY_RATE = {"hot drink": "standard", "eat-in food": "standard", "cold take-away": "zero", "soft drink": "standard"}


def vat_in(gross: Decimal, category: str) -> Decimal:
    """The VAT included in a VAT-inclusive ``gross`` amount."""
    rate = RATES[CATEGORY_RATE[category]]
    return (gross * rate / (1 + rate)).quantize(Decimal("0.01"), ROUND_HALF_UP)


def vat_return_lines(takings: dict[str, Decimal]) -> dict[str, Decimal]:
    """Totals for the quarter's return: output VAT and net sales."""
    output_vat = sum((vat_in(amount, category) for category, amount in takings.items()), Decimal("0"))
    gross = sum(takings.values(), Decimal("0"))
    return {"output_vat": output_vat, "net_sales": gross - output_vat}


def quarter_of(day) -> str:
    return f"{day.year}-Q{(day.month - 1) // 3 + 1}"


def quarterly_takings(sales: list[tuple[object, str, Decimal]]) -> dict[str, dict[str, Decimal]]:
    """Takings per VAT quarter and category from (day, category, gross) sales."""
    quarters: dict[str, dict[str, Decimal]] = {}
    for day, category, gross in sales:
        bucket = quarters.setdefault(quarter_of(day), {})
        bucket[category] = bucket.get(category, Decimal("0")) + gross
    return dict(sorted(quarters.items()))


def flat_rate_vat(gross_turnover: Decimal, flat_rate: Decimal = Decimal("0.125")) -> Decimal:
    """VAT due under the flat rate scheme at the catering rate."""
    return (gross_turnover * flat_rate).quantize(Decimal("0.01"), ROUND_HALF_UP)

