// The team roster: players, their positions and how they bat.
export interface Player {
  number: number;
  name: string;
  positions: string[];
  bats: "L" | "R" | "S";
}

export const POSITIONS = ["P", "C", "1B", "2B", "3B", "SS", "LF", "CF", "RF", "DH"];

export function validatePlayer(p: Player): Player {
  if (!Number.isInteger(p.number) || p.number < 0 || p.number > 99) throw new Error(`bad shirt number for ${p.name}`);
  for (const pos of p.positions) if (!POSITIONS.includes(pos)) throw new Error(`unknown position ${pos}`);
  return p;
}

export function byNumber(players: Player[]): Player[] {
  const seen = new Set<number>();
  for (const p of players) {
    if (seen.has(p.number)) throw new Error(`two players wear number ${p.number}`);
    seen.add(p.number);
  }
  return [...players].sort((a, b) => a.number - b.number);
}

