// Batting lineups: nine batters, each at a position they play, no position twice (DH bats for the pitcher).
import type { Player } from "./roster.ts";

export interface Slot {
  order: number;
  number: number;
  position: string;
}

export function checkLineup(slots: Slot[], roster: Player[]): string[] {
  const problems: string[] = [];
  if (slots.length !== 9) problems.push(`a lineup has 9 batters, not ${slots.length}`);
  const seen = new Set<string>();
  for (const slot of slots) {
    const player = roster.find((p) => p.number === slot.number);
    if (!player) problems.push(`#${slot.number} is not on the roster`);
    else if (slot.position !== "DH" && !player.positions.includes(slot.position)) {
      problems.push(`${player.name} does not play ${slot.position}`);
    }
    if (seen.has(slot.position)) problems.push(`${slot.position} is filled twice`);
    seen.add(slot.position);
  }
  return problems;
}


export function battingCard(slots: Slot[], roster: Player[]): string[] {
  return [...slots]
    .sort((a, b) => a.order - b.order)
    .map((s) => {
      const player = roster.find((p) => p.number === s.number);
      return `${s.order}. ${player ? player.name : `#${s.number}`} (${s.position})`;
    });
}

export function benched(slots: Slot[], roster: Player[]): Player[] {
  const playing = new Set(slots.map((s) => s.number));
  return roster.filter((p) => !playing.has(p.number));
}

export function leftHandedBatters(slots: Slot[], roster: Player[]): number {
  return slots.filter((s) => roster.find((p) => p.number === s.number)?.bats === "L").length;
}

