"""Address labels for the courier: up to five address lines of 35 characters, then postcode and reference."""

from __future__ import annotations

import re
import textwrap

POSTCODE = re.compile(r"^[A-Z]{1,2}\d[A-Z\d]? ?\d[A-Z]{2}$")
WIDTH = 35


def label_lines(name: str, address: list[str], postcode: str, reference: str) -> list[str]:
    postcode = postcode.strip().upper()
    if not POSTCODE.match(postcode):
        raise ValueError(f"postcode {postcode!r} does not look right")
    lines = [name[:WIDTH]]
    for part in address:
        lines += textwrap.wrap(part, WIDTH) or [""]
    if len(lines) > 5:
        raise ValueError("address too long for the label")
    return lines + [postcode, f"Ref {reference}"]


SERVICE_CODES = {"next-day": "ND", "two-day": "2D", "saturday": "SAT"}


def barcode_text(reference: str, service: str, weight_kg: float) -> str:
    """What the label barcode encodes: service code, reference and weight in grams."""
    code = SERVICE_CODES.get(service)
    if code is None:
        raise ValueError(f"unknown service {service!r}")
    return f"{code}{reference.replace('-', '')}{round(weight_kg * 1000):06d}"


def manifest_line(reference: str, postcode: str, weight_kg: float) -> str:
    return f"{reference:<12}{postcode.upper():<9}{weight_kg:>7.2f}"

