      const response = await fetchImpl(`${base}/resorts/${encodeURIComponent(resort)}/report`);
      if (!response.ok) throw new Error(`snow report for ${resort}: HTTP ${response.status}`);
      return (await response.json()) as SnowReport;
    },
  };
}

