// The lift status board: open, on hold for wind, or closed, with the reason shown to skiers.
export type LiftState = "open" | "wind-hold" | "closed";

export interface Lift {
  name: string;
  state: LiftState;
  reason?: string;
  nextCheck?: string;
}

export function boardLine(lift: Lift): string {
  switch (lift.state) {
    case "open":
      return `${lift.name}: open`;
    case "wind-hold":
      return `${lift.name}: on hold for wind${lift.nextCheck ? `, next check ${lift.nextCheck}` : ""}`;
    default:
      return `${lift.name}: closed${lift.reason ? ` (${lift.reason})` : ""}`;
  }
}

export function openCount(lifts: Lift[]): { open: number; total: number } {
  return { open: lifts.filter((l) => l.state === "open").length, total: lifts.length };
}


export function summaryForRadio(lifts: Lift[]): string {
  const { open, total } = openCount(lifts);
  const held = lifts.filter((l) => l.state === "wind-hold").map((l) => l.name);
  const parts = [`${open} of ${total} lifts open`];
  if (held.length > 0) parts.push(`on hold for wind: ${held.join(", ")}`);
  return parts.join("; ");
}

export function nextChecks(lifts: Lift[]): string[] {
  return lifts
    .filter((l) => l.state === "wind-hold" && l.nextCheck)
    .sort((a, b) => (a.nextCheck ?? "").localeCompare(b.nextCheck ?? ""))
    .map((l) => `${l.nextCheck} ${l.name}`);
}

