// Where the archive scanner keeps its files.
import { join, resolve } from "node:path";

export const DATA_DIR = resolve("data");

export function scanPath(accession: string, page: number, dir = DATA_DIR): string {
  if (!/^\d{4}\.\d{1,4}(\.\d{1,3})?$/.test(accession)) throw new Error(`bad accession number ${accession}`);
  return join(dir, "scans", accession, `p${String(page).padStart(3, "0")}.tif`);
}

export function cataloguePath(dir = DATA_DIR): string {
  return join(dir, "catalogue.jsonl");
}

