// The scan catalogue: one JSON line per scanned page.
import { appendFile, mkdir, readFile } from "node:fs/promises";
import { dirname } from "node:path";

export interface ScanRecord {
  accession: string;
  page: number;
  file: string;
  scannedAt: string;
  dpi: number;
}

export async function addRecord(path: string, record: ScanRecord): Promise<void> {
  if (record.dpi < 300) throw new Error("archive scans must be at least 300 dpi");
  await mkdir(dirname(path), { recursive: true });
  await appendFile(path, JSON.stringify(record) + "\n");
}

export async function readRecords(path: string): Promise<ScanRecord[]> {
  try {
    return (await readFile(path, "utf8")).split("\n").filter(Boolean).map((line) => JSON.parse(line));
  } catch {
    return [];
  }
}

