// The accession register: each object or document gets YEAR.LOT(.ITEM) when it enters the collection.
export interface Accession {
  number: string;
  title: string;
  donor: string;
  received: string;
  pages?: number;
}

export function nextLot(register: Accession[], year: number): string {
  const lots = register
    .map((a) => a.number.split("."))
    .filter(([y]) => Number(y) === year)
    .map(([, lot]) => Number(lot));
  return `${year}.${(lots.length ? Math.max(...lots) : 0) + 1}`;
}

export function unscanned(register: Accession[], scanned: Set<string>): Accession[] {
  return register.filter((a) => (a.pages ?? 0) > 0 && !scanned.has(a.number));
}

