"""Reorders from the growers: how many pots to order when a line is at or below its reorder level."""

from __future__ import annotations

import math

from .stock import Line

TRAY_SIZES = {"9cm": 18, "1l": 12, "2l": 8, "3l": 6}


def order_quantity(line: Line, target: int) -> int:
    """Pots to order to bring the bench back up to ``target``, in whole trays."""
    if line.on_bench > line.reorder_at:
        return 0
    tray = TRAY_SIZES.get(line.pot, 1)
    return math.ceil(max(0, target - line.on_bench) / tray) * tray


def order_sheet(lines: list[Line], targets: dict[str, int]) -> list[tuple[str, str, int]]:
    rows = []
    for line in lines:
        qty = order_quantity(line, targets.get(line.plant, line.reorder_at * 3))
        if qty:
            rows.append((line.plant, line.pot, qty))
    return rows


GROWERS = {"Lavender": "Hillside Herbs", "Salvia": "Hillside Herbs", "Hosta": "Shade Plants Direct"}


def orders_by_grower(rows: list[tuple[str, str, int]]) -> dict[str, list[str]]:
    """Order lines grouped by the grower who supplies each plant."""
    grouped: dict[str, list[str]] = {}
    for plant, pot, qty in rows:
        grouped.setdefault(GROWERS.get(plant, "unassigned"), []).append(f"{qty} x {plant} ({pot})")
    return dict(sorted(grouped.items()))

