// Receipts printed at the stall: one line per item, then the total.
import type { ShopConfig } from "./config.ts";

export interface Item {
  name: string;
  quantity: number;
  unitPrice: number;
}

const money = new Intl.NumberFormat("en-GB", { style: "currency", currency: "EUR" });

export function receipt(items: Item[], config: ShopConfig, at = new Date()): string {
  const lines = [config.stallName, at.toISOString().slice(0, 16).replace("T", " "), ""];
  let total = 0;
  for (const item of items) {
    const amount = Math.round(item.quantity * item.unitPrice * 100) / 100;
    total += amount;
    lines.push(`${item.quantity} x ${item.name}`.padEnd(24) + money.format(amount).padStart(10));
  }
  lines.push("".padEnd(34, "-"), "TOTAL".padEnd(24) + money.format(total).padStart(10));
  if (!config.vatRegistered) lines.push("", "Not VAT registered");
  return lines.join("\n") + "\n";
}

