// Stall stock: what was packed for the fair, what sold, and what to make before the next one.
export interface StockLine {
  item: string;
  packed: number;
  sold: number;
}

export function remaining(lines: StockLine[]): Record<string, number> {
  const left: Record<string, number> = {};
  for (const line of lines) {
    if (line.sold > line.packed) throw new Error(`${line.item}: sold more than was packed`);
    left[line.item] = line.packed - line.sold;
  }
  return left;
}

export function toMake(lines: StockLine[], minimum = 5): string[] {
  return lines
    .filter((l) => l.packed - l.sold < minimum)
    .sort((a, b) => b.sold - a.sold)
    .map((l) => `${l.item}: make ${minimum - (l.packed - l.sold)} more`);
}


export function bestSellers(lines: StockLine[], count = 3): string[] {
  return [...lines]
    .sort((a, b) => b.sold / b.packed - a.sold / a.packed || b.sold - a.sold)
    .slice(0, count)
    .map((l) => `${l.item} (${Math.round((l.sold / l.packed) * 100)}% sold)`);
}

export function packingList(lines: StockLine[]): Record<string, number> {
  // Pack a fifth more than sold last time, and never fewer than five of anything.
  const list: Record<string, number> = {};
  for (const l of lines) list[l.item] = Math.max(5, Math.ceil(l.sold * 1.2));
  return list;
}

