"""The guild's quilt raffle: ticket books, sales and a reproducible draw."""

from __future__ import annotations

import random
from dataclasses import dataclass, field

TICKETS_PER_BOOK = 20
PRICE_PENCE = 100


@dataclass
class Raffle:
    books: dict[int, str] = field(default_factory=dict)  # book number -> member selling it
    sold: dict[int, str] = field(default_factory=dict)  # ticket number -> buyer

    def issue_book(self, member: str) -> range:
        number = len(self.books) + 1
        self.books[number] = member
        first = (number - 1) * TICKETS_PER_BOOK + 1
        return range(first, first + TICKETS_PER_BOOK)

    def sell(self, ticket: int, buyer: str) -> None:
        if ticket in self.sold:
            raise ValueError(f"ticket {ticket} is already sold")
        if not 1 <= ticket <= len(self.books) * TICKETS_PER_BOOK:
            raise ValueError(f"ticket {ticket} has not been issued")
        self.sold[ticket] = buyer

    def takings_pence(self) -> int:
        return len(self.sold) * PRICE_PENCE

    def draw(self, prizes: int, seed: int) -> list[tuple[int, str]]:
        rng = random.Random(seed)
        winners = rng.sample(sorted(self.sold), k=min(prizes, len(self.sold)))
        return [(t, self.sold[t]) for t in winners]


def seller_totals(raffle: Raffle) -> dict[str, int]:
    """Tickets sold per member, from the books they were given."""
    totals: dict[str, int] = {member: 0 for member in raffle.books.values()}
    for ticket in raffle.sold:
        totals[raffle.books[(ticket - 1) // TICKETS_PER_BOOK + 1]] += 1
    return dict(sorted(totals.items(), key=lambda kv: (-kv[1], kv[0])))


def announce(winners: list[tuple[int, str]], prizes: list[str]) -> list[str]:
    return [f"{prize}: ticket {ticket} ({buyer})" for (ticket, buyer), prize in zip(winners, prizes)]

