export async function bookConsignment(trainId: string, tonnes: number, commodity: string): Promise<string> {
  const wagons = wagonsNeeded(tonnes, commodity);
  const response = await carrier.post(`/trains/${trainId}/bookings`, { wagons, tonnes, commodity });
