// How many wagons a consignment needs, by commodity.
const CAPACITY_TONNES: Record<string, number> = { stone: 72, timber: 48, containers: 60, grain: 66 };

export function wagonsNeeded(tonnes: number, commodity: string): number {
  const capacity = CAPACITY_TONNES[commodity];
  if (capacity === undefined) throw new Error(`no wagon type for ${commodity}`);
  if (tonnes <= 0) throw new Error("tonnes must be positive");
  return Math.ceil(tonnes / capacity);
}

