// Freight train paths: which trains run on a day, and the booking cut-off before departure.
export interface TrainPath {
  id: string;
  from: string;
  to: string;
  departs: string; // HH:MM, UTC
  days: string[]; // "mon".."sun"
}

const DAYS = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];
const CUTOFF_HOURS = 18;

export function trainsOn(paths: TrainPath[], date: string): TrainPath[] {
  const day = DAYS[new Date(`${date}T12:00:00Z`).getUTCDay()];
  return paths.filter((p) => p.days.includes(day)).sort((a, b) => a.departs.localeCompare(b.departs));
}

export function bookingCutoff(path: TrainPath, date: string): Date {
  const departure = new Date(`${date}T${path.departs}:00Z`);
  return new Date(departure.getTime() - CUTOFF_HOURS * 3_600_000);
}

export function stillBookable(path: TrainPath, date: string, now: Date): boolean {
  return now.getTime() < bookingCutoff(path, date).getTime();
}


export function weeklyPaths(paths: TrainPath[]): Record<string, string[]> {
  const week: Record<string, string[]> = {};
  for (const day of DAYS) week[day] = paths.filter((p) => p.days.includes(day)).map((p) => p.id).sort();
  return week;
}

export function departureLabel(path: TrainPath): string {
  return `${path.id} ${path.from} to ${path.to}, ${path.departs} (${path.days.join("/")})`;
}

