from __future__ import annotations

PINTS_PER_CRATE = 20


def load_sheet(orders: list[dict]) -> dict:
    pints = sum(o["pints"] for o in orders)
    extras: dict[str, int] = {}
    for o in orders:
        for item in o.get("extras") or []:
            extras[item] = extras.get(item, 0) + 1
    return {"pints": pints, "crates": -(-pints // PINTS_PER_CRATE), "extras": dict(sorted(extras.items()))}

