"""Weekly bills for the milk round's customers."""

from __future__ import annotations

from collections import defaultdict
from decimal import Decimal

PRICES = {"pint": Decimal("0.95"), "eggs": Decimal("2.40"), "orange juice": Decimal("1.85"), "yoghurt": Decimal("1.20")}


def weekly_bills(deliveries: list[dict]) -> dict[str, Decimal]:
    """One entry per delivery day: {"house": ..., "pints": n, "extras": [...]}."""
    bills: dict[str, Decimal] = defaultdict(lambda: Decimal("0.00"))
    for delivery in deliveries:
        bills[delivery["house"]] += PRICES["pint"] * delivery["pints"]
        for item in delivery.get("extras") or []:
            bills[delivery["house"]] += PRICES[item]
    return dict(sorted(bills.items()))


def bill_lines(house: str, total: Decimal, paid_by_card: bool) -> list[str]:
    lines = [house, f"This week: {total:.2f} pounds"]
    lines.append("Paid by card on file, thank you." if paid_by_card else "Please leave payment in the bottle by Saturday.")
    return lines


def holiday_credit(bill: Decimal, days_away: int, days_in_week: int = 7) -> Decimal:
    """Customers away for part of the week are not charged for the days the float skips them."""
    if not 0 <= days_away <= days_in_week:
        raise ValueError("days away must be within the week")
    return (bill * Decimal(days_in_week - days_away) / Decimal(days_in_week)).quantize(Decimal("0.01"))


def street_totals(bills: dict[str, Decimal]) -> dict[str, Decimal]:
    """Totals per street, for the round's weekly sheet."""
    streets: dict[str, Decimal] = defaultdict(lambda: Decimal("0.00"))
    for house, amount in bills.items():
        streets[house.split(" ", 1)[1] if " " in house else house] += amount
    return dict(sorted(streets.items()))

