import Papa from "papaparse";
import { toVolunteer } from "./volunteers.ts";
import type { Volunteer } from "./volunteers.ts";

export function importVolunteers(text: string): { volunteers: Volunteer[]; errors: string[] } {
  const parsed = Papa.parse<Record<string, string>>(text, { header: true });
  const volunteers: Volunteer[] = [];
  const errors: string[] = [];
  parsed.data.forEach((row, i) => {
    try {
      volunteers.push(toVolunteer(row));
    } catch (error) {
      errors.push(`row ${i + 2}: ${(error as Error).message}`);
    }
  });
  return { volunteers, errors };
}

