// A census volunteer: who they are and which enumeration districts they can cover.
export interface Volunteer {
  name: string;
  email: string;
  districts: string[];
  hasCar: boolean;
}

export function toVolunteer(row: Record<string, string>): Volunteer {
  const name = (row.name ?? "").trim();
  const email = (row.email ?? "").trim().toLowerCase();
  if (!name) throw new Error("name is missing");
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) throw new Error(`bad email ${JSON.stringify(email)}`);
  const districts = (row.districts ?? "").split(";").map((part) => part.trim()).filter(Boolean);
  return { name, email, districts, hasCar: /^(y|yes|true)$/i.test((row.car ?? "").trim()) };
}

