repo.src/districts.ts:
// Enumeration districts: how many volunteers each needs, and which are still short.
import type { Volunteer } from "./volunteers.ts";

export interface District {
  code: string;
  households: number;
  rural: boolean;
}

export function volunteersNeeded(d: District): number {
  const perVolunteer = d.rural ? 60 : 120;
  return Math.max(1, Math.ceil(d.households / perVolunteer));
}

export function shortfall(districts: District[], volunteers: Volunteer[]): Record<string, number> {
  const short: Record<string, number> = {};
  for (const d of districts) {
    const covering = volunteers.filter((v) => v.districts.includes(d.code) && (!d.rural || v.hasCar)).length;
    const missing = volunteersNeeded(d) - covering;
    if (missing > 0) short[d.code] = missing;
  }
  return short;
}


export function assign(districts: District[], volunteers: Volunteer[]): Record<string, string[]> {
  const plan: Record<string, string[]> = {};
  const taken = new Set<string>();
  for (const d of [...districts].sort((a, b) => volunteersNeeded(b) - volunteersNeeded(a))) {
    plan[d.code] = [];
    for (const v of volunteers) {
      if (plan[d.code].length >= volunteersNeeded(d)) break;
      if (taken.has(v.email) || !v.districts.includes(d.code) || (d.rural && !v.hasCar)) continue;
      plan[d.code].push(v.name);
      taken.add(v.email);
    }
  }
  return plan;
}

