"""Expense categories for the bookkeeping stubs, guessed from a bank line's description."""

from __future__ import annotations

RULES = [
    ("software", ("licence", "subscription", "hosting", "domain renewal")),
    ("travel", ("rail", "taxi", "parking", "fuel")),
    ("office", ("stationery", "printer", "paper", "rent")),
    ("subsistence", ("cafe", "coffee", "lunch")),
]


def categorise(description: str) -> str:
    text = description.lower()
    for category, words in RULES:
        if any(word in text for word in words):
            return category
    return "uncategorised"


def totals_by_category(lines: list[tuple[str, float]]) -> dict[str, float]:
    totals: dict[str, float] = {}
    for description, amount in lines:
        category = categorise(description)
        totals[category] = round(totals.get(category, 0.0) + amount, 2)
    return dict(sorted(totals.items()))


MONTHS = ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")


def monthly_summary(lines: list[tuple[str, str, float]]) -> dict[str, dict[str, float]]:
    """Totals per month and category from (YYYY-MM-DD, description, amount) lines."""
    summary: dict[str, dict[str, float]] = {}
    for day, description, amount in lines:
        bucket = summary.setdefault(f"{MONTHS[int(day[5:7]) - 1]} {day[:4]}", {})
        category = categorise(description)
        bucket[category] = round(bucket.get(category, 0.0) + amount, 2)
    return summary


def unexplained(lines: list[tuple[str, float]], limit: float = 250.0) -> list[str]:
    """Large uncategorised spending the bookkeeper should ask about."""
    return [description for description, amount in lines if amount >= limit and categorise(description) == "uncategorised"]

