// Passage schedule for the lock flight: boats go through in convoys to save water.
export interface Booking {
  boat: string;
  lengthM: number;
  direction: "up" | "down";
}

export interface Convoy {
  direction: "up" | "down";
  start: string;
  boats: string[];
}

const LOCK_LENGTH_M = 22;

export function convoys(bookings: Booking[], starts: Record<"up" | "down", string[]>): Convoy[] {
  const result: Convoy[] = [];
  for (const direction of ["up", "down"] as const) {
    const queue = bookings.filter((b) => b.direction === direction);
    const slots = [...starts[direction]];
    while (queue.length > 0) {
      const start = slots.shift();
      if (!start) throw new Error(`not enough ${direction} passages for the bookings`);
      const boats: string[] = [];
      let length = 0;
      while (queue.length > 0 && length + queue[0].lengthM <= LOCK_LENGTH_M) {
        const next = queue.shift()!;
        boats.push(next.boat);
        length += next.lengthM;
      }
      if (boats.length === 0) throw new Error(`${queue[0].boat} is too long for the locks`);
      result.push({ direction, start, boats });
    }
  }
  return result;
}

