// Water used by the flight: every passage empties each chamber into the pound below.
export const CHAMBER_CUBIC_M: Record<string, number> = { "lock-1": 95, "lock-2": 92, "lock-3": 101, "lock-4": 98 };

export function passageWater(locks: string[]): number {
  return locks.reduce((sum, lock) => {
    const volume = CHAMBER_CUBIC_M[lock];
    if (volume === undefined) throw new Error(`unknown lock ${lock}`);
    return sum + volume;
  }, 0);
}

export function dailyWater(convoys: { up: number; down: number }): number {
  const flight = Object.keys(CHAMBER_CUBIC_M);
  // A convoy going down can use chambers left full by one coming up, so a pair costs one passage of water.
  const paired = Math.min(convoys.up, convoys.down);
  const single = convoys.up + convoys.down - 2 * paired;
  return (paired + single) * passageWater(flight);
}

