from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal


@dataclass(frozen=True)
class Gift:
    donor: str
    salutation: str
    amount: Decimal
    gift_aid: bool


def thank_you_list(gifts: list[Gift], minimum: Decimal = Decimal("25")) -> list[dict]:
    totals: dict[str, dict] = {}
    for gift in gifts:
        entry = totals.setdefault(gift.donor, {"donor": gift.donor, "salutation": gift.salutation,
                                               "total": Decimal("0"), "gift_aid": False})
        entry["total"] += gift.amount
        entry["gift_aid"] = entry["gift_aid"] or gift.gift_aid
    return sorted((t for t in totals.values() if t["total"] >= minimum), key=lambda t: t["donor"])

