"""Gift Aid: the parish can reclaim basic-rate tax on gifts from donors who have made a declaration."""

from __future__ import annotations

from decimal import ROUND_DOWN, Decimal

BASIC_RATE = Decimal("0.20")


def reclaimable(amount: Decimal) -> Decimal:
    """Tax reclaimable on a gift: 25p for every pound given, at a 20% basic rate."""
    return (amount * BASIC_RATE / (1 - BASIC_RATE)).quantize(Decimal("0.01"), rounding=ROUND_DOWN)


def claim_schedule(gifts: list[tuple[str, Decimal, bool]]) -> tuple[list[tuple[str, Decimal]], Decimal]:
    """Donor and amount for each gift with a declaration, and the total to claim."""
    rows = [(donor, amount) for donor, amount, declared in gifts if declared]
    total = sum((reclaimable(amount) for _, amount in rows), Decimal("0.00"))
    return rows, total


def tax_year(day) -> str:
    """UK tax years run from 6 April, e.g. "2026-27"."""
    start = day.year if (day.month, day.day) >= (4, 6) else day.year - 1
    return f"{start}-{str(start + 1)[2:]}"


def claims_by_tax_year(gifts: list[tuple[str, Decimal, bool, object]]) -> dict[str, Decimal]:
    """Reclaimable tax per tax year from (donor, amount, declared, day) gifts."""
    totals: dict[str, Decimal] = {}
    for _, amount, declared, day in gifts:
        if declared:
            year = tax_year(day)
            totals[year] = totals.get(year, Decimal("0.00")) + reclaimable(amount)
    return dict(sorted(totals.items()))

