// Monthly invoices for dog owners: group walks at one rate, dogs that must walk alone at another.
import type { Walk } from "./walks.ts";

export const RATES = { group: 12, solo: 18 };

export interface Owner {
  name: string;
  dogs: string[];
  soloOnly: string[];
}

export function invoiceLines(owner: Owner, walks: Walk[], month: string): string[] {
  const mine = walks.filter((w) => owner.dogs.includes(w.dog) && w.startedAt.toISOString().startsWith(month));
  const lines: string[] = [];
  let total = 0;
  for (const dog of owner.dogs) {
    const count = mine.filter((w) => w.dog === dog).length;
    if (count === 0) continue;
    const rate = owner.soloOnly.includes(dog) ? RATES.solo : RATES.group;
    total += count * rate;
    lines.push(`${dog}: ${count} walks at ${rate} = ${count * rate}`);
  }
  lines.push(`Total for ${month}: ${total}`);
  return lines;
}

export function busiestWalker(walks: Walk[]): string | undefined {
  const counts = new Map<string, number>();
  for (const w of walks) counts.set(w.walker, (counts.get(w.walker) ?? 0) + 1);
  return [...counts].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0]?.[0];
}


export function walksPerDay(walks: Walk[]): Map<string, number> {
  const days = new Map<string, number>();
  for (const w of walks) {
    const day = w.startedAt.toISOString().slice(0, 10);
    days.set(day, (days.get(day) ?? 0) + 1);
  }
  return new Map([...days].sort((a, b) => a[0].localeCompare(b[0])));
}

export function distanceByDog(walks: Walk[]): Record<string, number> {
  const totals: Record<string, number> = {};
  for (const w of walks) totals[w.dog] = Math.round(((totals[w.dog] ?? 0) + w.distanceKm) * 10) / 10;
  return totals;
}

