"""The harvest log: who picked what, where and when, in kilograms."""

from __future__ import annotations

import csv
from collections import defaultdict
from dataclasses import dataclass
from datetime import date
from pathlib import Path


@dataclass(frozen=True)
class Harvest:
    day: date
    plot: str
    crop: str
    kg: float


def load_log(path: Path) -> list[Harvest]:
    with open(path, newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    return [Harvest(date.fromisoformat(r["day"]), r["plot"], r["crop"], float(r["kg"])) for r in rows]


def summarize(harvests: list[Harvest], plot: str | None = None, cutoff: date | None = None) -> dict[str, float]:
    totals: dict[str, float] = defaultdict(float)
    for h in harvests:
        if plot and h.plot != plot:
            continue
        if cutoff and h.day > cutoff:
            continue
        totals[h.crop] += h.kg
    return {crop: round(kg, 1) for crop, kg in sorted(totals.items())}

