"""Plot holders at the community garden and their yearly rent."""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal

RENT_PER_SQ_M = Decimal("0.42")
CONCESSION = Decimal("0.5")


@dataclass(frozen=True)
class Plot:
    number: str
    holder: str
    area_sq_m: int
    concession: bool = False

    def rent(self) -> Decimal:
        rent = RENT_PER_SQ_M * self.area_sq_m
        return (rent * CONCESSION if self.concession else rent).quantize(Decimal("0.01"))


def rent_roll(plots: list[Plot]) -> list[str]:
    return [f"{p.number:>4}  {p.holder:<24} {p.area_sq_m:>4} m2  {p.rent():>7}" for p in sorted(plots, key=lambda p: p.number)]


def vacancies(plots: list[Plot], all_numbers: list[str]) -> list[str]:
    let = {p.number for p in plots}
    return [n for n in all_numbers if n not in let]


def total_rent(plots: list[Plot]) -> Decimal:
    return sum((p.rent() for p in plots), Decimal("0.00"))


def holders_with_several_plots(plots: list[Plot]) -> dict[str, list[str]]:
    by_holder: dict[str, list[str]] = {}
    for p in plots:
        by_holder.setdefault(p.holder, []).append(p.number)
    return {holder: sorted(numbers) for holder, numbers in by_holder.items() if len(numbers) > 1}

