// Pricing settings from config/pricing.json.
import { readFileSync } from "node:fs";

export interface PricingConfig {
  currency: string;
  rounding: "none" | "nearest-5p" | "down-10p";
  volumeDiscounts: { minQuantity: number; percent: number }[];
}

export function parsePricing(text: string): PricingConfig {
  const raw = JSON.parse(text);
  const rounding = raw.rounding ?? "none";
  if (!["none", "nearest-5p", "down-10p"].includes(rounding)) throw new Error(`unknown rounding ${rounding}`);
  const tiers = [...(raw.volumeDiscounts ?? [])].sort((a, b) => a.minQuantity - b.minQuantity);
  return { currency: raw.currency ?? "GBP", rounding, volumeDiscounts: tiers };
}

export function loadPricing(path = "config/pricing.json"): PricingConfig {
  return parsePricing(readFileSync(path, "utf8"));
}

