// Print-shop prices: unit price by product, volume discount, then rounding of the line total (pence).
import type { PricingConfig } from "./config.ts";

export const UNIT_PENCE: Record<string, number> = { "a5-flyer": 12, "a4-poster": 85, "business-card": 4 };

function roundPence(pence: number, mode: PricingConfig["rounding"]): number {
  switch (mode) {
    case "nearest-5p":
      return Math.round(pence / 5) * 5;
    case "down-10p":
      return Math.floor(pence / 10) * 10;
    default:
      return Math.round(pence);
  }
}

export function lineTotal(product: string, quantity: number, config: PricingConfig): number {
  const unit = UNIT_PENCE[product];
  if (unit === undefined) throw new Error(`unknown product ${product}`);
  const tier = [...config.volumeDiscounts].reverse().find((t) => quantity >= t.minQuantity);
  const discounted = unit * quantity * (1 - (tier?.percent ?? 0) / 100);
  return roundPence(discounted, config.rounding);
}

