// Proof approval: an order goes to print only once the customer approves the latest proof.
export type ProofState = "sent" | "approved" | "changes-requested";

export interface Proof {
  version: number;
  state: ProofState;
  note?: string;
}

export function latest(proofs: Proof[]): Proof | undefined {
  return [...proofs].sort((a, b) => b.version - a.version)[0];
}

export function readyToPrint(proofs: Proof[]): boolean {
  return latest(proofs)?.state === "approved";
}

export function nextVersion(proofs: Proof[]): number {
  const current = latest(proofs);
  if (current?.state === "approved") throw new Error("the latest proof is approved; reopen the order to change it");
  return (current?.version ?? 0) + 1;
}

