from __future__ import annotations

from datetime import datetime, timedelta

DEFAULT_LEAD_MINUTES = 30


def reminder_time(appointment: datetime, lead_minutes: int | None = None) -> datetime:
    """The moment to send the reminder for ``appointment``: ``lead_minutes`` before it."""
    minutes = DEFAULT_LEAD_MINUTES if lead_minutes is None else lead_minutes
    if minutes <= 0:
        raise ValueError("lead time must be positive")
    return appointment - timedelta(minutes=minutes)

