"""Check-up recalls: how soon each patient should come back, by risk band."""

from __future__ import annotations

from datetime import date, timedelta

RECALL_MONTHS = {"low": 18, "medium": 12, "high": 6, "child": 6}


def recall_date(last_visit: date, band: str) -> date:
    months = RECALL_MONTHS[band]
    year = last_visit.year + (last_visit.month - 1 + months) // 12
    month = (last_visit.month - 1 + months) % 12 + 1
    return date(year, month, min(last_visit.day, 28))


def due_for_recall(patients: list[tuple[str, date, str]], today: date, window_days: int = 30) -> list[str]:
    """Patients whose recall date falls within the next ``window_days`` days, or has passed."""
    limit = today + timedelta(days=window_days)
    return sorted(name for name, last, band in patients if recall_date(last, band) <= limit)


LETTER = """Dear {name},

It is time for your check-up at the practice. Please call us on 01632 960 214 or book online.
"""


def recall_letters(patients: list[tuple[str, date, str]], today: date) -> list[str]:
    return [LETTER.format(name=name) for name in due_for_recall(patients, today)]


def overdue_by_months(last_visit: date, band: str, today: date) -> int:
    due = recall_date(last_visit, band)
    if due >= today:
        return 0
    return (today.year - due.year) * 12 + today.month - due.month

