// Court bookings at the tennis club, and the hours they add up to.
export interface Booking {
  member: string;
  court: number;
  start: string; // ISO, UTC
  minutes: number;
}

export function inMonth(bookings: Booking[], month: string): Booking[] {
  return bookings.filter((b) => b.start.startsWith(month));
}

export function hoursByMember(bookings: Booking[]): Map<string, number> {
  const totals = new Map<string, number>();
  for (const b of bookings) totals.set(b.member, (totals.get(b.member) ?? 0) + b.minutes / 60);
  return new Map([...totals].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])));
}

