// Court rules: only floodlit courts after sunset, and a cap on peak-time bookings per member.
export const COURTS = [
  { number: 1, surface: "hard", floodlit: true },
  { number: 2, surface: "hard", floodlit: true },
  { number: 3, surface: "grass", floodlit: false },
];

export function canBook(court: number, startHour: number, sunsetHour: number): boolean {
  const info = COURTS.find((c) => c.number === court);
  if (!info) throw new Error(`no court ${court}`);
  return startHour < sunsetHour || info.floodlit;
}

export function peakBookingsLeft(existing: { start: string }[], limit = 3): number {
  const peak = existing.filter((b) => {
    const hour = Number(b.start.slice(11, 13));
    return hour >= 17 && hour < 21;
  }).length;
  return Math.max(0, limit - peak);
}


export function courtsFree(bookings: { court: number; start: string; minutes: number }[], at: string): number[] {
  const t = Date.parse(at);
  const busy = new Set(
    bookings.filter((b) => Date.parse(b.start) <= t && t < Date.parse(b.start) + b.minutes * 60_000).map((b) => b.court),
  );
  return COURTS.map((c) => c.number).filter((n) => !busy.has(n));
}

export function surfaceOf(court: number): string {
  const info = COURTS.find((c) => c.number === court);
  if (!info) throw new Error(`no court ${court}`);
  return info.surface;
}

