"""Matching the supplier names on scanned invoices to our supplier list."""

from __future__ import annotations

import re

SUPPLIERS = {
    "S01": "Fenland Growers Co-operative",
    "S02": "Hollow Lane Orchards",
    "S03": "Marsh End Mushrooms Ltd",
    "S04": "Brightwater Salad Company",
}


def normalise(name: str) -> str:
    name = re.sub(r"\b(ltd|limited|co-operative|company|co)\b\.?", "", name.lower())
    return re.sub(r"[^a-z0-9]+", " ", name).strip()


def match_supplier(name: str) -> str | None:
    """The supplier id for an invoice's supplier name, or None if there is no exact match."""
    wanted = normalise(name)
    for supplier_id, known in SUPPLIERS.items():
        if normalise(known) == wanted:
            return supplier_id
    return None

