"""Produce on the shop floor: deliveries in, sales out, and what went to waste."""

from __future__ import annotations

from collections import defaultdict
from decimal import Decimal


def wastage(delivered: dict[str, Decimal], sold: dict[str, Decimal], on_hand: dict[str, Decimal]) -> dict[str, Decimal]:
    """Kilograms lost per product over the week: delivered, less sold, less still on hand."""
    lost = {}
    for product, kg in delivered.items():
        gone = kg - sold.get(product, Decimal("0")) - on_hand.get(product, Decimal("0"))
        if gone > 0:
            lost[product] = gone
    return dict(sorted(lost.items(), key=lambda kv: -kv[1]))


def spend_by_supplier(lines: list[tuple[str, str, Decimal]]) -> dict[str, Decimal]:
    """Total spend per supplier id from (supplier, product, amount) lines."""
    totals: dict[str, Decimal] = defaultdict(Decimal)
    for supplier, _, amount in lines:
        totals[supplier] += amount
    return dict(sorted(totals.items()))


def price_per_kg(lines: list[tuple[str, str, Decimal, Decimal]]) -> dict[str, Decimal]:
    """Average cost per kg for each product from (supplier, product, kg, amount) invoice lines."""
    kg: dict[str, Decimal] = defaultdict(Decimal)
    spent: dict[str, Decimal] = defaultdict(Decimal)
    for _, product, weight, amount in lines:
        kg[product] += weight
        spent[product] += amount
    return {p: (spent[p] / kg[p]).quantize(Decimal("0.01")) for p in sorted(kg) if kg[p] > 0}


def reduce_to_clear(on_hand: dict[str, Decimal], days_left: dict[str, int]) -> list[str]:
    """Produce in stock with two days or less of shelf life: reduce the price before it is lost."""
    return sorted(p for p, kg in on_hand.items() if kg > 0 and days_left.get(p, 99) <= 2)

