// Booklet imposition: which pages share a printed sheet side when the booklet is folded.
export function impose(pageCount: number): [number, number][] {
  const total = Math.ceil(pageCount / 4) * 4;
  const pairs: [number, number][] = [];
  for (let i = 0; i < total / 2; i++) {
    const outer = total - i;
    const inner = i + 1;
    pairs.push(i % 2 === 0 ? [outer, inner] : [inner, outer]);
  }
  return pairs;
}

