// Newsletter issues: page counts that suit the booklet, and the print shop's deadline.
export interface Issue {
  number: number;
  title: string;
  pages: string[];
  printBy: string; // YYYY-MM-DD
}

export function blankPagesNeeded(issue: Issue): number {
  return (4 - (issue.pages.length % 4)) % 4;
}

export function checkIssue(issue: Issue, today: string): string[] {
  const problems: string[] = [];
  if (issue.pages.length === 0) problems.push("the issue has no pages");
  if (blankPagesNeeded(issue) > 1) problems.push(`${blankPagesNeeded(issue)} blank pages at the back`);
  if (issue.printBy < today) problems.push(`print deadline ${issue.printBy} has passed`);
  return problems;
}


export function contentsPage(issue: Issue): string[] {
  return issue.pages.map((page, i) => {
    const heading = page.split("\n")[0].replace(/^#+\s*/, "").trim();
    return `${String(i + 1).padStart(2)}  ${heading || "(untitled)"}`;
  });
}

export function nextIssue(previous: Issue, printBy: string): Issue {
  return { number: previous.number + 1, title: "", pages: [], printBy };
}

