const DEFAULT_DAYS: Record<Notice["category"], number> = { event: 30, "lost-and-found": 14, "for-sale": 21, council: 90 };

export function expiryOf(notice: Notice): string {
  if (notice.expires) return notice.expires;
  const date = new Date(`${notice.posted}T00:00:00Z`);
  date.setUTCDate(date.getUTCDate() + DEFAULT_DAYS[notice.category]);
  return date.toISOString().slice(0, 10);
}

export function current(notices: Notice[], today: string): Notice[] {
  return notices
    .filter((n) => n.posted <= today && expiryOf(n) >= today)
    .sort((a, b) => b.posted.localeCompare(a.posted) || a.id.localeCompare(b.id));
}


export function byCategory(notices: Notice[]): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const n of notices) counts[n.category] = (counts[n.category] ?? 0) + 1;
  return counts;
}

export function validateNotice(input: Partial<Notice>): string[] {
  const problems: string[] = [];
  if (!input.title || input.title.trim().length < 3) problems.push("title is too short");
  if (input.title && input.title.length > 80) problems.push("title is longer than 80 characters");
  if (!input.postedBy) problems.push("who is posting it?");
  if (input.expires && input.posted && input.expires < input.posted) problems.push("expiry is before the posting date");
  return problems;
}

