"""Hive inspection records as the beekeepers enter them, checked before upload."""

from __future__ import annotations

from datetime import date

TEMPERS = ("calm", "nervous", "defensive")


def check_record(record: dict) -> list[str]:
    problems = []
    if not str(record.get("hive", "")).startswith("H-"):
        problems.append("hive ids look like H-01")
    try:
        if date.fromisoformat(record["date"]) > date.today():
            problems.append("inspection date is in the future")
    except (KeyError, ValueError):
        problems.append("date must be YYYY-MM-DD")
    if record.get("temper", "calm") not in TEMPERS:
        problems.append(f"temper must be one of {', '.join(TEMPERS)}")
    if not isinstance(record.get("queen_seen", False), bool):
        problems.append("queen_seen must be true or false")
    return problems


def ready_to_upload(records: list[dict]) -> tuple[list[dict], dict[int, list[str]]]:
    good, bad = [], {}
    for i, record in enumerate(records):
        problems = check_record(record)
        if problems:
            bad[i] = problems
        else:
            good.append(record)
    return good, bad

