// Uploads photos with a few workers, retrying failures after a delay.
export interface UploadQueueOptions {
  concurrency?: number;
  retries?: number;
  retryDelayMs?: number;
  sleep?: (ms: number) => Promise<void>;
}

export type Uploader = (file: string) => Promise<void>;

export class UploadQueue {
  private readonly concurrency: number;
  private readonly retries: number;
  private readonly retryDelayMs: number;
  private readonly sleep: (ms: number) => Promise<void>;

  constructor(options: UploadQueueOptions = {}) {
    this.concurrency = options.concurrency ?? 1;
    this.retries = options.retries ?? 0;
    this.retryDelayMs = options.retryDelayMs ?? 250;
    this.sleep = options.sleep ?? ((ms) => new Promise((resolve) => setTimeout(resolve, ms)));
  }

  async run(files: string[], upload: Uploader): Promise<{ done: string[]; failed: string[] }> {
    const done: string[] = [];
    const failed: string[] = [];
    const pending = [...files];
    const worker = async () => {
      for (let file = pending.shift(); file !== undefined; file = pending.shift()) {
        if (await this.attempt(file, upload)) done.push(file);
        else failed.push(file);
      }
    };
    await Promise.all(Array.from({ length: this.concurrency }, worker));
    return { done, failed };
  }

  private async attempt(file: string, upload: Uploader): Promise<boolean> {
    for (let tries = 0; tries <= this.retries; tries++) {
      try {
        await upload(file);
        return true;
      } catch {
        if (tries < this.retries) await this.sleep(this.retryDelayMs);
      }
    }
    return false;
  }
}

