// Photo files from the camera card: class and pupil codes from the file names, and the upload manifest.
import { basename } from "node:path";

const NAME = /^(?<className>[A-Z0-9]{2,4})_(?<pupil>\d{3})_(?<shot>\d{2})\.(jpe?g|cr3)$/i;

export interface Photo {
  file: string;
  className: string;
  pupil: string;
  shot: number;
  raw: boolean;
}

export function parsePhoto(file: string): Photo | undefined {
  const groups = NAME.exec(basename(file))?.groups;
  if (!groups) return undefined;
  return { file, className: groups.className.toUpperCase(), pupil: groups.pupil, shot: Number(groups.shot), raw: /\.cr3$/i.test(file) };
}

export function manifest(files: string[]): { byClass: Record<string, number>; unrecognised: string[] } {
  const byClass: Record<string, number> = {};
  const unrecognised: string[] = [];
  for (const file of files) {
    const photo = parsePhoto(file);
    if (!photo) unrecognised.push(basename(file));
    else if (!photo.raw) byClass[photo.className] = (byClass[photo.className] ?? 0) + 1;
  }
  return { byClass, unrecognised };
}

export function missingPupils(photos: Photo[], register: Record<string, string[]>): Record<string, string[]> {
  const missing: Record<string, string[]> = {};
  for (const [className, pupils] of Object.entries(register)) {
    const seen = new Set(photos.filter((p) => p.className === className).map((p) => p.pupil));
    const absent = pupils.filter((pupil) => !seen.has(pupil));
    if (absent.length) missing[className] = absent;
  }
  return missing;
}

