from __future__ import annotations

from dataclasses import dataclass, field


@dataclass
class Session:
    name: str
    day: str
    places: int
    children: list[str] = field(default_factory=list)

    def book(self, child: str) -> bool:
        if child in self.children:
            raise ValueError(f"{child} is already booked on {self.name}")
        if len(self.children) >= self.places:
            return False
        self.children.append(child)
        return True

    @property
    def free(self) -> int:
        return self.places - len(self.children)

