"""Session prices: a fee per child, less for siblings, and funded places on the council's support scheme."""

from __future__ import annotations

from decimal import Decimal

FEE = Decimal("12.50")
SIBLING_DISCOUNT = Decimal("0.25")


def family_price(children: list[dict]) -> Decimal:
    """children: [{"name": ..., "supported": bool}] in booking order."""
    paying = [c for c in children if not c.get("supported")]
    total = sum((FEE if i == 0 else FEE * (1 - SIBLING_DISCOUNT) for i in range(len(paying))), Decimal("0.00"))
    return total.quantize(Decimal("0.01"))


def receipt(children: list[dict]) -> list[str]:
    lines = [f"{c['name']}: {'funded place' if c.get('supported') else 'booked'}" for c in children]
    return lines + [f"To pay: {family_price(children)} pounds"]


def refund(paid: Decimal, days_before: int) -> Decimal:
    """Cancellations: a full refund up to 7 days before, half up to 2 days before, nothing after that."""
    if days_before >= 7:
        return paid
    if days_before >= 2:
        return (paid / 2).quantize(Decimal("0.01"))
    return Decimal("0.00")


def term_income(bookings: list[list[dict]]) -> Decimal:
    return sum((family_price(children) for children in bookings), Decimal("0.00"))

