"""Membership fees by category; the club part halves for anyone joining between October and March."""

from __future__ import annotations

from datetime import date
from decimal import Decimal

ANNUAL = {"senior": Decimal("85"), "junior": Decimal("30"), "family": Decimal("150"), "social": Decimal("20")}
ASSOCIATION_LEVY = {"senior": Decimal("12"), "junior": Decimal("6"), "family": Decimal("24"), "social": Decimal("0")}


def fee(category: str, joined: date) -> Decimal:
    """The club fee plus the paddling association's levy, which is never reduced."""
    club = ANNUAL[category]
    if joined.month >= 10 or joined.month < 4:
        club = club / 2
    return (club + ASSOCIATION_LEVY[category]).quantize(Decimal("0.01"))


def family_saving(categories: list[str]) -> Decimal:
    """What a household saves with a family membership compared with paying for each member."""
    separate = sum((ANNUAL[c] + ASSOCIATION_LEVY[c] for c in categories), Decimal("0"))
    family = ANNUAL["family"] + ASSOCIATION_LEVY["family"]
    return max(Decimal("0"), separate - family)


def renewal_reminders(members: list[tuple[str, str, date]], today: date) -> list[str]:
    """Members whose membership runs out within the next 30 days."""
    return sorted(name for name, _, until in members if 0 <= (until - today).days <= 30)

