// Progress of a send: the addresses already done, saved after each message so a run can resume.
import { existsSync, readFileSync, writeFileSync } from "node:fs";

export function loadProgress(path: string): Set<string> {
  return existsSync(path) ? new Set(JSON.parse(readFileSync(path, "utf8")) as string[]) : new Set();
}

export function markSent(path: string, progress: Set<string>, address: string): void {
  progress.add(address);
  writeFileSync(path, JSON.stringify([...progress]));
}

export function remaining(addresses: string[], progress: Set<string>): string[] {
  return addresses.filter((a) => !progress.has(a));
}

