// lettercart command line: `lettercart send --list FILE --template FILE [--resume]`.
import { readFileSync } from "node:fs";
import { parseArgs } from "node:util";
import { fileURLToPath } from "node:url";
import { loadProgress, markSent, remaining } from "./progress.ts";

export async function main(argv: string[], send: (to: string, body: string) => Promise<void>): Promise<number> {
  const { positionals, values } = parseArgs({
    args: argv,
    allowPositionals: true,
    options: {
      list: { type: "string" },
      template: { type: "string" },
      resume: { type: "boolean", default: false },
      progress: { type: "string", default: ".lettercart-progress.json" },
    },
  });
  if (positionals[0] !== "send" || !values.list || !values.template) {
    console.error("usage: lettercart send --list FILE --template FILE [--resume]");
    return 2;
  }
  const addresses = readFileSync(values.list, "utf8").split("\n").map((l) => l.trim()).filter(Boolean);
  const body = readFileSync(values.template, "utf8");
  const progress = values.resume ? loadProgress(values.progress) : new Set<string>();
  for (const to of remaining(addresses, progress)) {
    await send(to, body);
    markSent(values.progress, progress, to);
  }
  return 0;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  process.exitCode = await main(process.argv.slice(2), async (to) => console.log(`sent to ${to}`));
}

