// Converting recipe quantities into the book's metric units.
import type { RecipeConfig } from "./config.ts";

const TO_GRAMS: Record<string, number> = { g: 1, kg: 1000, oz: 28.35, lb: 453.6 };
const TO_ML: Record<string, number> = { ml: 1, l: 1000, tsp: 5, tbsp: 15, cup: 240 };
const METRIC = new Set(["g", "kg", "ml", "l", "tsp", "tbsp"]);

function roundTo(value: number, step: number): number {
  return Math.round(value / step) * step;
}

export function convert(quantity: number, unit: string, config: RecipeConfig): { quantity: number; unit: string } {
  if (METRIC.has(unit)) return { quantity, unit };
  if (config.strictUnits) throw new Error(`non-metric unit "${unit}" in a metric recipe`);
  if (unit in TO_GRAMS) return { quantity: roundTo(quantity * TO_GRAMS[unit], config.roundTo), unit: "g" };
  if (unit in TO_ML) return { quantity: roundTo(quantity * TO_ML[unit], config.roundTo), unit: "ml" };
  return { quantity, unit };
}

