// Scaling a recipe to a different yield: quantities scale linearly and are rounded to the book's step.
export interface Ingredient {
  name: string;
  quantity: number;
  unit: string;
}

export function scale(ingredients: Ingredient[], fromYield: number, toYield: number, step = 5): Ingredient[] {
  if (fromYield <= 0 || toYield <= 0) throw new Error("yields must be positive");
  const factor = toYield / fromYield;
  return ingredients.map((i) => {
    const raw = i.quantity * factor;
    const rounded = ["g", "ml"].includes(i.unit) ? Math.max(step, Math.round(raw / step) * step) : Math.round(raw * 4) / 4;
    return { ...i, quantity: rounded };
  });
}

export function bakersPercent(ingredients: Ingredient[], flour = "flour"): Record<string, number> {
  const base = ingredients.find((i) => i.name === flour);
  if (!base) throw new Error("no flour in the recipe");
  return Object.fromEntries(ingredients.map((i) => [i.name, Math.round((i.quantity / base.quantity) * 1000) / 10]));
}

