"""Admission prices for the tide mill."""

from __future__ import annotations

from decimal import Decimal

PRICES = {"adult": Decimal("8.50"), "child": Decimal("4.00"), "concession": Decimal("6.50")}
FAMILY = Decimal("22.00")  # two adults and up to three children


def price(adults: int, children: int, concessions: int = 0) -> Decimal:
    if min(adults, children, concessions) < 0:
        raise ValueError("ticket counts cannot be negative")
    total = adults * PRICES["adult"] + children * PRICES["child"] + concessions * PRICES["concession"]
    if adults == 2 and 1 <= children <= 3 and concessions == 0:
        total = min(total, FAMILY)
    return total

