"""School group visits: one adult per eight children (adults free), priced per child, booked by term."""

from __future__ import annotations

import math
from decimal import Decimal

CHILD_PRICE = Decimal("3.50")
CHILDREN_PER_ADULT = 8


def adults_needed(children: int) -> int:
    return max(1, math.ceil(children / CHILDREN_PER_ADULT))


def group_price(children: int, adults: int) -> Decimal:
    if adults < adults_needed(children):
        raise ValueError(f"{children} children need at least {adults_needed(children)} adults")
    return CHILD_PRICE * children


def term_of(month: int) -> str:
    if month >= 9:
        return "autumn"
    return "spring" if month <= 4 else "summer"


def income_by_term(bookings: list[tuple[str, int, int]]) -> dict[str, Decimal]:
    """Income per term from (school, month, children) bookings."""
    totals: dict[str, Decimal] = {}
    for _, month, children in bookings:
        term = term_of(month)
        totals[term] = totals.get(term, Decimal("0")) + CHILD_PRICE * children
    return totals


def coaches_needed(children: int, adults: int, seats_per_coach: int = 53) -> int:
    """Coaches for the group, with everyone seated."""
    return math.ceil((children + adults) / seats_per_coach)

