// Cold-chain monitoring for the pharmacy's vaccine fridges: alert when a fridge stays too warm.
export interface MonitorOptions {
  maxTempC: number;
  alertAfterMinutes?: number;
}

export interface Reading {
  fridge: string;
  at: number; // epoch ms
  tempC: number;
}

export class ColdChainMonitor {
  private readonly maxTempC: number;
  private readonly alertAfterMs: number;
  private warmSince = new Map<string, number>();

  constructor(options: MonitorOptions) {
    this.maxTempC = options.maxTempC;
    this.alertAfterMs = (options.alertAfterMinutes ?? 30) * 60_000;
  }

  /** Returns an alert once the fridge has been above the limit for long enough. */
  record(reading: Reading): string | undefined {
    if (reading.tempC <= this.maxTempC) {
      this.warmSince.delete(reading.fridge);
      return undefined;
    }
    const since = this.warmSince.get(reading.fridge) ?? reading.at;
    this.warmSince.set(reading.fridge, since);
    if (reading.at - since >= this.alertAfterMs) {
      return `${reading.fridge} above ${this.maxTempC} C for ${Math.round((reading.at - since) / 60_000)} min`;
    }
    return undefined;
  }
}

