// Readings from the fridge sensors' hub, one "fridge,ISO time,temperature" line each.
import type { Reading } from "./monitor.ts";

export function parseReadings(text: string): Reading[] {
  return text
    .trim()
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      const [fridge, at, temp] = line.split(",");
      return { fridge, at: Date.parse(at), tempC: Number(temp) };
    });
}

