// Reads the sensor hub's feed and prints an alert line for the pharmacist's pager.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { ColdChainMonitor } from "./monitor.ts";
import { parseReadings } from "./sensors.ts";

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const monitor = new ColdChainMonitor({ maxTempC: 8 });
  for (const reading of parseReadings(readFileSync(process.argv[2] ?? "/var/lib/frostline/feed.csv", "utf8"))) {
    const alert = monitor.record(reading);
    if (alert) console.log(alert);
  }
}

