import { test } from "node:test";
import assert from "node:assert/strict";
import { ColdChainMonitor } from "../src/monitor.ts";
import { parseReadings } from "../src/sensors.ts";

const feed = parseReadings([
  "fridge-1,2026-11-07T08:00:00Z,6.0",
  "fridge-1,2026-11-07T08:05:00Z,8.6",
  "fridge-1,2026-11-07T08:20:00Z,9.1",
  "fridge-1,2026-11-07T08:40:00Z,9.4",
].join("\n"));

test("alerts after the configured time above the limit", () => {
  const monitor = new ColdChainMonitor({ maxTempC: 8, alertAfterMinutes: 15 });
  assert.deepEqual(feed.map((r) => monitor.record(r)), [
    undefined, undefined, "fridge-1 above 8 C for 15 min", "fridge-1 above 8 C for 35 min",
  ]);
});

test("thirty minutes by default", () => {
  const monitor = new ColdChainMonitor({ maxTempC: 8 });
  assert.deepEqual(feed.map((r) => monitor.record(r)), [undefined, undefined, undefined, "fridge-1 above 8 C for 35 min"]);
});

