// The excursion log: each spell above the limit, kept for the pharmacy's cold-chain audit.
export interface Excursion {
  fridge: string;
  from: number;
  to: number;
  peakC: number;
}

export function excursions(readings: { fridge: string; at: number; tempC: number }[], maxTempC: number): Excursion[] {
  const open = new Map<string, Excursion>();
  const done: Excursion[] = [];
  for (const r of [...readings].sort((a, b) => a.at - b.at)) {
    const current = open.get(r.fridge);
    if (r.tempC > maxTempC) {
      if (current) {
        current.to = r.at;
        current.peakC = Math.max(current.peakC, r.tempC);
      } else {
        open.set(r.fridge, { fridge: r.fridge, from: r.at, to: r.at, peakC: r.tempC });
      }
    } else if (current) {
      done.push(current);
      open.delete(r.fridge);
    }
  }
  return [...done, ...open.values()];
}

export function auditLine(e: Excursion): string {
  const minutes = Math.round((e.to - e.from) / 60_000);
  return `${e.fridge}: ${new Date(e.from).toISOString()} for ${minutes} min, peak ${e.peakC} C`;
}


export function stabilityAdvice(e: Excursion): string {
  const minutes = Math.round((e.to - e.from) / 60_000);
  if (e.peakC > 12 || minutes > 120) return "quarantine the stock and contact the manufacturer";
  if (e.peakC > 8) return "label the stock, keep using it, and record the excursion";
  return "no action needed";
}

export function monthlyReport(list: Excursion[], month: string): string[] {
  return list
    .filter((e) => new Date(e.from).toISOString().startsWith(month))
    .map((e) => `${auditLine(e)} -> ${stabilityAdvice(e)}`);
}
